window.QUESTION_BANK_CHUNKS["law_多选"]={"id":"law_多选","name":"建设工程安全生产法律法规—多选","questionCount":315,"type":"multiple","questions":[{"id":1,"type":"multiple","stem":"根据《建筑施工特种作业人员管理规定》（住建部令第60号），下列建筑施工人员属于特种作业的是（   ）。","options":["A．建筑电工","B．建筑起重信号司索工","C．建筑架子工","D．建筑起重机械安装拆卸工","E．经省级以上人民政府建设主管部门认定的其他特种作业"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_1"},{"id":2,"type":"multiple","stem":"根据《建筑施工特种作业人员管理规定》（住建部令第60号）规定，从事建筑施工特种作业的人员，应当具备下列哪些基本条件（   ）。","options":["A．年满18周岁","B．经二级及以上医院体检合格，且无器质性心脏病、癫痫病、美尼尔氏综合症、眩晕症、癔病、震颤麻痹、精神病、吸毒史以及其他不适合从事建筑施工特种作业的疾病和生理缺陷","C．5年内不存在因违反建筑施工安全生产管理有关规定作业，造成生产安全事故或者受到刑事处罚的情形；","D．高中以上学历","E．初中以上学历"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_2"},{"id":3,"type":"multiple","stem":"根据《建筑施工特种作业人员管理规定》（住建部令第60号），建筑施工特种作业人员的考核内容应当包括（   ）。","options":["A．安全技术理论","B．安全思想教育","C．安全技术措施","D．操作技能","E．职业卫生考核"],"answer":"AD","hasImage":false,"image":null,"globalId":"law_多选_3"},{"id":4,"type":"multiple","stem":"根据《建筑施工特种作业人员管理规定》（住建部令第60号），在施工中发生危及人身安全的紧急情况时，建筑施工特种作业人员有权（   ）或者（   ）。","options":["A．停止作业","B．在采取必要的应急措施后撤离危险区域","C．报告单位负责人","D．视情况而定","E．报告项目负责人"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_4"},{"id":5,"type":"multiple","stem":"根据《建筑施工特种作业人员管理规定》（住建部令第60号），特种作业人员所在用人单位应当履行下列哪些职责（   ）。","options":["A．施工前，向建筑施工特种作业人员详细说明有关安全施工的技术要求","B．合理安排作业时间，连续作业不得超过4小时且间隔休息时间不得少于1小时","C．根据建筑施工特种作业人员年龄、身体健康状况、作业环境等情况合理安排作业内容和时段","D．查向建筑施工特种作业人员提供安全防护用具和安全防护服装，并书面告知岗位操作规程、违章操作的危害","E．制止和纠正相关违章指挥、强令冒险作业、违反操作规程的行为"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_5"},{"id":6,"type":"multiple","stem":"根据《建筑施工特种作业人员管理规定》（住建部令第60号），建筑施工特种作业人员申请延期复核，应当提交的材料（   ）。","options":["A．培训机构出具的安全作业培训记录或者证书","B．3个月内的体检合格报告","C．资格证书申请表","D．单位证明","E．承诺书"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_6"},{"id":7,"type":"multiple","stem":"根据《建筑施工特种作业人员管理规定》（住建部令第60号），下面说法正确的是（  ）","options":["A．资格证书实行电子证照。电子证照标准由国务院住房城乡建设主管部门制定","B．资格证书在全国范围内有效，有效期为3年","C．建筑施工特种作业人员需要延续资格证书有效期的，应当在资格证书有效期届满10个工作日前向原考核发证机关提出延期复核申请","D．考核发证机关应当通过政务服务平台公布资格证书申请条件、申请程序、考核日程、审核时限和监督电话，并办理资格证书申请受理等事项","E．资格证书不得伪造、涂改，不得倒卖、出租、出借或者以其他形式非法转让"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_7"},{"id":8,"type":"multiple","stem":"根据《建筑施工特种作业人员管理规定》（住建部令第60号），建筑施工特种作业人员有（   ）情形之一的，考核发证机关应当撤销其资格证书。","options":["A．行政机关工作人员滥用职权、玩忽职守发放资格证书","B．超越法定职权发放资格证书","C．违反法定程序发放资格证书","D．对不具备申请资格或者不符合法定条件的申请人发放资格证书","E．未按期办理延期复核手续或者延期复核不合格"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_8"},{"id":9,"type":"multiple","stem":"根据《建筑施工特种作业人员管理规定》（住建部令第60号），建筑施工特种作业人员有（   ）情形之一的，考核发证机关应当注销资格证书。","options":["A．未按期办理延期复核手续或者延期复核不合格","B．死亡或者丧失行为能力","C．资格证书被依法撤销、吊销","D．法律、法规规定的应当注销资格证书的其他情形","E．考核发证机关工作人员违法核发资格证书的"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_9"},{"id":10,"type":"multiple","stem":"根据《建筑施工企业安全生产管理机构设置及专职安全生产管理人员配备办法》，建筑施工企业安全生产管理机构具有（   ）职责。","options":["A．组织或者参与拟定企业安全生产规章制度、操作规程和生产安全事故应急救援预案；","B．组织或者参与拟定企业安全生产教育、培训相关制度和计划，如实记录安全生产教育和培训情况","C．组织或者参与企业应急救援演练","D．督促落实企业淘汰和限制使用危及生产安全的落后工艺、设备和材料","E．负责组织危险性较大工程安全专项施工方案专家论证会"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_10"},{"id":11,"type":"multiple","stem":"根据《建筑施工企业安全生产管理机构设置及专职安全生产管理人员配备办法》，企业安全生产管理机构组织开展企业在建项目的安全生产检查工作，重点检查包括（   ）。","options":["A．项目负责人在内的项目全员安全生产责任履行情况","B．及时排查生产安全事故隐患","C．提出改进安全生产管理的建议","D．企业安全生产规章制度是否完善","E.制止和纠正违章指挥、强令冒险作业、违反操作规程的行为，并记入企业和项目安全管理档案；"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_11"},{"id":12,"type":"multiple","stem":"根据《建筑施工企业安全生产管理机构设置及专职安全生产管理人员配备办法》，建筑施工企业安全生产管理机构专职安全生产管理人员的配备应满足的要求包括（   ）。","options":["A．建筑施工总承包一级资质企业应不少于4人","B．建筑施工专业承包一级资质企业应不少于3人","C．建筑施工专业承包一级资质企业应不少于2人","D．建筑施工劳务分包资质企业应不少于2人","E.企业施工活动涉及建筑起重机械的，在上述基础上，至少增加配备1名机械类专职安全生产管理人员。"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_12"},{"id":13,"type":"multiple","stem":"根据《建筑施工企业安全生产管理机构设置及专职安全生产管理人员配备办法》，施工总承包企业应当在分包合同中明确分包企业项目专职安全生产管理人员的配备要求，且人员数量应当至少满足（  ）","options":["A．50人以下的，配备不少于1人","B．50人～200人的，配备不少于1人","C．50人～200人的，配备不少于2人","D．200人以上的，配备不少于3人，且不得少于工程施工人员总人数的1%，并根据所承担的分部分项工程施工危险程度增加","E.200人以上的，配备不少于2人"],"answer":"ACD","hasImage":false,"image":null,"globalId":"law_多选_13"},{"id":14,"type":"multiple","stem":"根据《建筑施工企业安全生产管理机构设置及专职安全生产管理人员配备办法》，下列属于项目安全生产管理机构以及专职安全生产管理人员安全生产职责的是（   ）","options":["A．组织或参与项目应急救援演练；","B．及时复核现场安全生产条件，制止和纠正违章指挥、强令冒险作业、违反操作规程的行为，并记入企业安全管理档案；","C．组织或参与拟定项目安全生产教育和培训，如实记录安全生产教育和培训情况；","D．组织建立并落实企业主要负责人施工现场带班检查和项目负责人施工现场带班生产制度，明确工作内容、职责权限和考核奖惩等要求；","E．及时、如实报告生产安全事故"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_14"},{"id":15,"type":"multiple","stem":"根据《建筑施工企业安全生产管理机构设置及专职安全生产管理人员配备办法》，项目安全总监应当协助项目经理履行下列（   ）安全生产管理职责。","options":["A．督促落实项目安全生产标准化建设工作","B．督促落实项目安全生产教育和培训计划","C．组织落实项目安全风险分级管控和隐患排查治理双重预防工作机制","D．及时、如实报告生产安全事故","E．组织编制危险性较大工程安全专项施工方案"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_15"},{"id":16,"type":"multiple","stem":"根据《建筑施工企业安全生产管理机构设置及专职安全生产管理人员配备办法》，总承包单位按照建筑面积配备配备项目专职安全生产管理人员应当满足（   ）。","options":["A．建筑面积1万平方米以下的工程不少于1人","B．建筑面积1~5万平方米的工程不少于3人","C．建筑面积5万平方米及以上的工程不少于3人，且每增加5万平方米，应当至少增加1名专职安全生产管理人员","D．建筑面积1~5万平方米的工程不少于2人","E．建筑面积5万平方米及以上的工程不少于3人即可"],"answer":"ACD","hasImage":false,"image":null,"globalId":"law_多选_16"},{"id":17,"type":"multiple","stem":"根据《建筑施工企业安全生产管理机构设置及专职安全生产管理人员配备办法》，总承包单位按照市政基础设施工程项目按照工程合同价款配备项目专职安全生产管理人员，应满足（   ）","options":["A．5000万元以下的工程不少于1人","B．5000万～1亿元的工程不少于1人","C．5000万～2亿元的工程不少于2人","D．2亿元以上的项目不少于3人，且每增加2亿元，应当至少增加1名专职安全生产管理人员；","E．1亿元及以上的工程按专业配备专职安全生产管理人员"],"answer":"ACD","hasImage":false,"image":null,"globalId":"law_多选_17"},{"id":18,"type":"multiple","stem":"根据《陕西省建筑施工安全生产标准化考评实施细则》，安全生产标准化考评包括（   ）。","options":["A．建筑施工项目安全生产标准化考评","B．建筑施工项目负责人安全生产标准化","C．建筑施工安全生产标准化监督","D．建筑施工企业安全生产标准化考评","E．不定期抽查"],"answer":"AD","hasImage":false,"image":null,"globalId":"law_多选_18"},{"id":19,"type":"multiple","stem":"根据《陕西省建筑施工安全生产标准化考评实施细则》，工程项目实行施工总承包的，由总包、专业承包单位的（   ）共同组成自评机构开展项目安全生产标准化考评工作。","options":["A．项目负责人","B．技术负责人","C．专职安全员","D．劳务班组长","E．监理工程师"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_19"},{"id":20,"type":"multiple","stem":"根据《陕西省建筑施工安全生产标准化考评实施细则》，工程项目完工后办理竣工验收前，建筑施工企业向工程项目考评主体提交的项目安全生产标准化自评材料（   ）","options":["A．建筑施工项目安全生产标准化月自评表","B．建筑施工项目安全生产标准化月自评汇总表","C．企业对项目安全生产标准化工作季度评价汇总表","D．工程项目发生生产安全责任事故情况","E．工程项目施工期间因安全生产受到住房城乡建设主管部门奖惩情况"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_20"},{"id":21,"type":"multiple","stem":"根据《陕西省建筑施工安全生产标准化考评实施细则》，工程项目安全生产标准化考评的结果有（   ）。","options":["A．优良","B．优秀","C．合格","D．不合格","E．以上均不对"],"answer":"ACD","hasImage":false,"image":null,"globalId":"law_多选_21"},{"id":22,"type":"multiple","stem":"根据《陕西省建筑施工安全生产标准化考评实施细则》，具备（   ）的工程项目，安全生产标准化优先评定为优良。","options":["A．获得全国建筑工程安全文明标准化工地、省级文明工地或者工程所在地安全文明施工观摩工地的","B．安全生产、文明施工受到省级以上有关部门表彰奖励的","C．在施工安全技术和标准化研发方面获得专利或省级以上科学技术奖的","D．安全无事故的工程项目","E．工程项目施工期间仅出现过生产安全一般事故的"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_22"},{"id":23,"type":"multiple","stem":"根据《陕西省建筑施工安全生产标准化考评实施细则》，工程项目具有（   ），安全生产标准化评定为不合格。","options":["A．发生生产安全责任事故的","B．因存在安全隐患在一年内受到建设行政主管部门2次及以上限期整改、停工整改、通报批评、行政处罚的","C．月自评资料不健全、不连续或企业未对项目标准化工作进行季度检查评分的","D．办理竣工验收前建筑施工企业未提交工程项目自评及申请材料或项目自评材料弄虚作假的","E．工程项目按规定进行月度自评检查评分的"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_23"},{"id":24,"type":"multiple","stem":"根据《陕西省建筑施工安全生产标准化考评实施细则》，建筑施工企业在办理安全生产许可证延期时，应向考评主体提交（   ）。","options":["A．建筑施工企业安全生产标准化年周期自评表","B．近三年内企业承建项目的安全生产标准化考评结果汇总表","C．因安全生产受到住房城乡建设主管部门奖惩情况","D．承建项目发生生产安全责任事故情况","E．陕西省建筑施工企业安全生产标准化评申请表"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_24"},{"id":25,"type":"multiple","stem":"根据《陕西省建筑施工安全生产标准化考评实施细则》，建筑施工企业在考评周期内（三年）未发生生产安全责任事故，并具备（   ），可优先评为优良。","options":["A．竣工项目考评优良率达到10%以上的","B．在建工程全部实行关键岗位实名制管理的","C．省级文明工地数量达到已考评项目总数量10%以上；或者获得全国建筑工程安全文明标准化工地2个及以上、或者获得省级文明工地观摩工地1个及以上的","D．获得省级以上有关部门安全生产和文明施工表彰奖励的","E．在施工安全技术和标准化研发方面获得专利或省级以上科学技术奖的"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_25"},{"id":26,"type":"multiple","stem":"根据《陕西省建筑施工安全生产标准化考评实施细则》，建筑施工企业具有（   ），安全生产标准化考评结果为不合格。","options":["A．未按规定开展企业自评工作或自评结果低于70分的","B．企业近三年所承建的项目发生较大及以上生产安全责任事故的","C．未按规定开展企业自评工作或自评结果低于60分的","D．企业近五年所承建的项目发生较大及以上生产安全责任事故的","E．企业近三年已竣工项目安全生产标准化考评不合格率超过5%的"],"answer":"ABE","hasImage":false,"image":null,"globalId":"law_多选_26"},{"id":27,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，下列（   ）属于建设工程项目经理必须负责组织的工作。","options":["A．组织编制施工组织设计","B．组织制定质量安全技术措施","C．组织编制、论证和实施危险性较大分部分项工程专项施工方案","D．组织质量安全技术交底","E．组织验收分部工程"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_27"},{"id":28,"type":"multiple","stem":"根据《安全生产责任保险实施办法》，安全生产责任保险工作应该坚持（   ）原则。","options":["A．风险防控","B．费率合理","C．理赔及时","D．一次性支付","E．费率统一"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_28"},{"id":29,"type":"multiple","stem":"根据《安全生产责任保险实施办法》，下列哪些行业应当投保安全生产责任保险。（   ）","options":["A．煤矿行业","B．非煤矿山行业","C．危险化学品行业","D．建筑施工行业","E．民用爆炸物品行业"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_29"},{"id":30,"type":"multiple","stem":"根据《安全生产责任保险实施办法》，承保安全生产责任保险的保险机构应当具有（   ）专业资质和能力。","options":["A．商业信誉情况","B．偿付能力水平","C．开展责任保险的业绩和规模","D．拥有风险管理专业人员的数量和相应专业资格情况","E．为生产经营单位提供事故预防服务情况"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_30"},{"id":31,"type":"multiple","stem":"根据《安全生产责任保险实施办法》，下列说法正确的是（   ）。","options":["A．生产经营单位投保安全生产责任保险的保障范围应当覆盖全体从业人员","B．保险机构可以开发适应各类生产经营单位安全生产保障需求的个性化保险产品","C．生产经营单位只对现场管理人员投保即可","D．保险机构只负责赔付保费，无需进行其他服务","E．生产经营单位可自愿选择是否投保安全生产责任保险"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_31"},{"id":32,"type":"multiple","stem":"根据《安全生产责任保险实施办法》，保险机构应当建立生产安全事故预防服务制度，协助投保的生产经营单位开展（   ）工作。","options":["A．安全生产和职业病防治宣传教育培训","B．安全风险辨识、评估和安全评价","C．安全生产标准化建设","D．安全生产应急预案编制和应急救援演练","E．安全环保设施改造"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_32"},{"id":33,"type":"multiple","stem":"根据《安全生产责任保险实施办法》，下列不正确的是（   ）。","options":["A．生产经营单位未按规定投保或续保的","B．将保费以各种形式摊派给从业人员个人的","C． 委托不合法的社会化服务机构开展事故预防工作的","D．生产经营单位为全体从业人员投保安全生产责任保险","E．保险机构按照合同约定及时赔偿保险金"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_33"},{"id":34,"type":"multiple","stem":"根据《建筑工程施工发包与承包违法行为认定查处管理办法》，下列属于违法发包的是（   ）。","options":["A．建设单位将工程发包给个人的","B．建设单位将工程发包给不具有相应资质的单位的","C．依法应当招标未招标或未按照法定招标程序发包的","D．建设单位设置不合理的招标投标条件，限制、排斥潜在投标人或者投标人的","E．建设单位将一个单位工程的施工分解成若干部分发包给不同的施工总承包或专业承包单位的。"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_34"},{"id":35,"type":"multiple","stem":"根据《建筑工程施工发包与承包违法行为认定查处管理办法》，下列属于非法转包的是（   ）。","options":["A．承包单位将其承包的全部工程转给其他单位或个人施工的","B．建设单位将工程发包给个人的","C．专业工程的发包单位不是该工程的施工总承包或专业承包单位的","D．承包单位通过采取合作、联营、个人承包等形式或名义，直接或变相将其承包的全部工程转给其他单位或个人施工的","E．建设单位将工程发包给不具有相应资质的单位的"],"answer":"ACD","hasImage":false,"image":null,"globalId":"law_多选_35"},{"id":36,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），建筑“三类人员”指的是（   ）。","options":["A．企业主要负责人","B．项目负责人","C．监理工程师","D．兼职安全生产管理人员","E．专职安全生产管理人员"],"answer":"ABE","hasImage":false,"image":null,"globalId":"law_多选_36"},{"id":37,"type":"multiple","stem":"根据《建筑施工企业安全生产许可证动态监管暂行办法》，下列说法正确的是（   ）。","options":["A．发生一般事故的，暂扣安全生产许可证10至30日","B．发生一般事故的，暂扣安全生产许可证30至60日","C．发生较大事故的，暂扣安全生产许可证30至60日","D．发生较大事故的，暂扣安全生产许可证60至90日","E．发生重大事故的，暂扣安全生产许可证90至120日"],"answer":"BDE","hasImage":false,"image":null,"globalId":"law_多选_37"},{"id":38,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），安全管理中“三违”指的是（   ）。","options":["A．违章指挥","B．违章作业","C．违反操作规章","D．违反劳动纪律","E．违背技术规定"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_38"},{"id":39,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），安全培训工作实行（   ）原则。","options":["A．统一规划","B．归口管理","C．分级实施","D．分类指导","E．教考分离"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_39"},{"id":40,"type":"multiple","stem":"根据《生产经营单位安全培训规定》，生产经营单位应当按照有关规定对本单位其他从业人员进行安全培训，对（   ）进行专门培训。","options":["A．新上岗人员","B．转岗人员","C．重新上岗人员","D．劳务派遣人员","E．实习学生"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_40"},{"id":41,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，下列说法正确的是（   ）。","options":["A．建设工程实行施工总承包的，可以由分包单位对施工现场的安全生产负总责","B．总承包单位和分包单位对分包工程的安全生产承担无限连带责任","C．分包单位应当服从总承包单位的安全生产管理，分包单位不服从管理导致生产安全事故的，由总承包单位承担主要责任","D．总承包单位应当自行完成建设工程主体结构的施工","E．建设工程实行施工总承包的，由总承包单位对施工现场的安全生产负总责"],"answer":"DE","hasImage":false,"image":null,"globalId":"law_多选_41"},{"id":42,"type":"multiple","stem":"根据《陕西省建设项目安全设施监督管理办法》，下列说法正确的是（   ）。","options":["A．跨县（市、区）的建设项目安全设施的设计审查和竣工验收由设区的市人民政府安全生产监督管理部门负责","B．跨设区市的建设项目安全设施的设计审查和竣工验收由设区的市人民政府安全生产监督管理部门负责","C．跨设区市的建设项目安全设施的设计审查和竣工验收由省级人民政府安全生产监督管理部门负责","D．跨县（市、区）的建设项目安全设施的设计审查和竣工验收由县级人民政府安全生产监督管理部门负责","E．以上说法均不对"],"answer":"AC","hasImage":false,"image":null,"globalId":"law_多选_42"},{"id":43,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，施工单位在采用（   ）时，应当对作业人员进行相应的安全生产教育培训。","options":["A．新工艺","B．新材料","C．新结构","D．新设备","E．新技术"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_43"},{"id":44,"type":"multiple","stem":"根据《生产安全事故应急预案管理办法》规定，生产经营单位应急预案分为（   ）。","options":["A．月度应急预案","B．专项应急预案","C．年度应急预案","D．综合应急预案","E．现场处置方案"],"answer":"BDE","hasImage":false,"image":null,"globalId":"law_多选_44"},{"id":45,"type":"multiple","stem":"根据《生产安全事故应急预案管理办法》，应急预案的编制应当符合（   ）。","options":["A．有关法律、法规、规章和标准的规定","B．全国的安全生产实际情况","C．全国范围的危险性分析情况","D．有明确、具体的应急程序和处置措施，并与其应急能力相适应","E．应急组织和人员的职责分工明确，并有具体的落实措施"],"answer":"ADE","hasImage":false,"image":null,"globalId":"law_多选_45"},{"id":46,"type":"multiple","stem":"根据《生产安全事故应急预案管理办法》，生产经营单位申报应急预案备案，应当提交（   ）。","options":["A．应急预案备案申报表","B．应急预案评审意见","C．风险评估结果和应急资源调查清单","D．应急预案电子文档","E．企业社会投诉和违法行为情况"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_46"},{"id":47,"type":"multiple","stem":"根据《生产安全事故应急预案管理办法》，有下列情形之一的，应急预案应当及时修订并归档（   ）。","options":["A．依据的法律、法规、规章、标准及上位预案中的有关规定发生重大变化的","B．应急指挥机构及其职责发生调整的","C．安全生产面临的风险发生重大变化的","D．重要应急资源发生重大变化的","E．在应急演练和事故应急救援中发现需要修订预案的重大问题的"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_47"},{"id":48,"type":"multiple","stem":"根据《建筑工程安全防护、文明施工措施费用及使用管理规定》（建办〔2005〕89号），建筑工程安全防护、文明施工措施费用是由（   ）组成。","options":["A．技术措施费","B．文明施工费","C．环境保护费","D．安全施工费","E．临时设施费"],"answer":"BCDE","hasImage":false,"image":null,"globalId":"law_多选_48"},{"id":49,"type":"multiple","stem":"根据《建筑工程安全防护、文明施工措施费用及使用管理规定》（建办〔2005〕89号），建筑工程安全防护、文明施工措施费用中的安全施工费由（   ）组成。","options":["A．临边、洞口安全防护费","B．交叉作业安全防护费","C．高处作业安全防护费","D．危险性较大工程安全措施费","E．现场围挡防护费"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_49"},{"id":50,"type":"multiple","stem":"根据《注册建造师管理规定》（建设部令第153号），注册建造师申请初始注册时应当具备（   ）。","options":["A．经考核认定或考试合格取得资格证书","B．受聘于两个相关单位","C．受聘于一个相关单位","D．达到继续教育要求","E．无较大刑事责任即可"],"answer":"ACD","hasImage":false,"image":null,"globalId":"law_多选_50"},{"id":51,"type":"multiple","stem":"根据《注册建造师管理规定》（建设部令第153号），建造师注册申请人有（   ）不予注册。","options":["A．不具有完全民事行为能力的","B．申请在两个或者两个以上单位注册的","C．未达到注册建造师继续教育要求的","D．受到刑事处罚，刑事处罚尚未执行完毕的","E．年龄超过65周岁的"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_51"},{"id":52,"type":"multiple","stem":"根据《注册建造师管理规定》（建设部令第153号），注册建造师有（   ），其注册证书和执业印章失效。","options":["A．聘用单位破产的","B．聘用单位被吊销营业执照的","C．聘用单位被吊销或者撤回资质证书的","D．注册有效期满且未延续注册的","E．死亡或不具有完全民事行为能力的"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_52"},{"id":53,"type":"multiple","stem":"根据《注册建造师管理规定》（建设部令第153号），取得资格证书的人员应当受聘于一个具有建设工程（   ）等一项或者多项资质的单位，经注册后方可从事相应的执业活动。","options":["A．勘察","B．设计","C．施工","D．监理","E．招标代理"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_53"},{"id":54,"type":"multiple","stem":"根据《注册建造师管理规定》（建设部令第153号），注册建造师可以从事（   ）。","options":["A．建设工程项目总承包管理","B．建设工程项目管理服务","C．建设工程技术经济咨询","D．建设工程项目施工管理","E．法律、行政法规和国务院建设主管部门规定的其他业务"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_54"},{"id":55,"type":"multiple","stem":"根据《注册建造师管理规定》（建设部令第153号），注册建造师享有（   ）权利。","options":["A．使用注册建造师名称","B．在本人执业活动中形成的文件上签字并加盖执业印章","C．对本人执业活动进行解释和辩护","D．接受继续教育","E．执行技术标准、规范和规程"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_55"},{"id":56,"type":"multiple","stem":"根据《注册建造师管理规定》（建设部令第153号），注册建造师应当履行（   ）义务。","options":["A．遵守法律、法规和有关管理规定，恪守职业道德","B．保证执业成果的质量，并承担相应责任","C．接受继续教育，努力提高执业水准","D．与当事人有利害关系的，应当主动回避","E．同时在两个或者两个以上单位受聘或者执业"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_56"},{"id":57,"type":"multiple","stem":"根据《注册建造师管理规定》（建设部令第153号），注册建造师不得有（   ）行为。","options":["A．不履行注册建造师义务","B．允许他人以自己的名义从事执业活动","C．涂改、倒卖、出租、出借或以其他形式非法转让资格证书、注册证书和执业印章","D．保证执业成果的质量，并承担相应责任","E．超出执业范围和聘用单位业务范围内从事执业活动"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_57"},{"id":58,"type":"multiple","stem":"用人单位要按照《用人单位职业健康监护监督管理办法》规定，组织接触职业病危害人员进行（   ）的职业健康检查。","options":["A．上岗前","B．在岗期间","C．离岗时","D．上岗后","E．离岗前"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_58"},{"id":59,"type":"multiple","stem":"根据《中华人民共和国职业病防治法》，关于职业病防治下列说法正确的是（   ）。","options":["A．不得安排未经上岗前体检的人员从事接触职业病危害的作业","B．不得安排有职业禁忌的劳动者从事其所禁忌的作业","C．不得安排孕期、哺乳期女职工从事对本人和胎儿、婴儿有危害的作业","D．不得安排未成年工从事接触职业病危害的作业","E．不得安排人员从事接触职业病危害的作业"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_59"},{"id":60,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，建筑施工现场的（   ）要做到三区分离。","options":["A．施工区","B．生活区","C．观摩区","D．办公区","E．活动区"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_60"},{"id":61,"type":"multiple","stem":"根据《中华人民共和国职业病防治法》，建设项目职业病防护设施设计专篇应当包括（   ）。","options":["A．设计的依据","B．建设项目概述","C．职业病防护设施和有关防控措施及其控制性能","D．职业病防治管理措施","E．可能出现的职业病危害事故的预防及应急措施"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_61"},{"id":62,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，施工单位从事建设工程的新建、扩建、改建和拆除等活动，应当具备国家规定的（   ）等条件，依法取得相应等级的资质证书，并在其资质等级许可的范围内承揽工程。","options":["A．注册资本","B．专业技术人员","C．技术装备","D．新型技术","E．新型设备"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_62"},{"id":63,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，某建筑构件公司由于安全资金投入不足造成二人受伤，（   ）应当对此承担责任。","options":["A．企业法定代表人","B．该公司总经理","C．该公司财务总监","D．该公司的安全管理人员","E．该公司的工会小组负责人"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_63"},{"id":64,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，生产经营单位与从业人员订立协议（   ）。","options":["A．除免或者减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议无效","B．减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议无效","C．除免或者减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议有效","D．减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议有效","E．除免或者减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议有效与否视情况而定"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_64"},{"id":65,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，设计单位、设计人应当对其编制的职业病防护设施设计专篇的（   ）负责。","options":["A．真实性","B．合法性","C．实用性","D．经济性","E．重要性"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_65"},{"id":66,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，负有安全生产监督管理职责的部门应当建立举报制度（   ）","options":["A．公开举报电话、信箱或者电子邮件地址","B．受理有关安全生产的举报","C．受理的举报事项经调查核实后，应当形成书面材料","D．需要落实整改措施的，报经有关负责人签字并督促落实","E．以上均不对"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_66"},{"id":67,"type":"multiple","stem":"根据《建筑工程五方责任主体项目负责人质量终身责任追究暂行办法》，建筑工程五方责任主体项目负责人分别是（   ）。","options":["A．建设单位项目负责人","B．勘察、设计单位项目负责人","C．施工单位法人代表","D．施工单位项目经理","E．监理单位总监理工程师"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_67"},{"id":68,"type":"multiple","stem":"根据《房屋建筑和市政基础设施工程施工安全监督规定》，施工安全监督机构应当具备（   ）条件。","options":["A．具有完整的组织体系，岗位职责明确","B．具有固定的工作场所，配备满足监督工作需要的仪器、设备、工具及安全防护用品","C．有健全的施工安全监督工作制度，具备与监督工作相适应的信息化管理条件","D．监督人员必须具有本科以上学历","E．以上说法均对"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_68"},{"id":69,"type":"multiple","stem":"根据《房屋建筑和市政基础设施工程施工安全监督规定》，施工安全监督机构安全监督人员应当具备（   ）条件。","options":["A．具有两年及以上施工安全管理经验","B．熟悉掌握相关法律法规和工程建设标准规范","C．经业务培训考核合格，取得相关执法证书","D．具有良好的职业道德","E．具有大专以上文化程度或初级及以上专业技术职称"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_69"},{"id":70,"type":"multiple","stem":"根据《房屋建筑和市政基础设施工程施工安全监督规定》，施工安全监督主要包括（   ）。","options":["A．抽查工程建设责任主体履行安全生产职责情况","B．抽查工程建设责任主体执行法律、法规、规章、制度及工程建设强制性标准情况","C．抽查建筑施工安全生产标准化开展情况","D．组织或参与工程项目施工安全事故的调查处理","E．依法对工程建设责任主体违法违规行为实施行政处罚"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_70"},{"id":71,"type":"multiple","stem":"根据《建设工程安全生产管理条例》（国务院令第393号），建设单位应当在拆除工程施工15日前，将（   ）报送建设工程所在地的县级以上地方人民政府建设行政主管部门或者其他有关部门备案。","options":["A．施工单位资质等级证明","B．拟拆除建筑物、构筑物及可能危及毗邻建筑的说明","C．拆除施工组织方案","D．堆放、清除废弃物的措施","E．扬尘治理方案"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_71"},{"id":72,"type":"multiple","stem":"根据《国务院关于特大安全事故行政责任追究的规定》的公布，旨在（   ）。","options":["A．为了有效地防范特大安全事故的发生","B．严肃追究特大安全事故的行政责任","C．保障人民群众生命安全","D．保障人民群众财产安全","E．严肃追究今后所有安全事故的行政责任"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_72"},{"id":73,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，施工单位采购、租赁的安全防护用具，应当具有下列资料：（   ）","options":["A．生产(制造)许可证","B．产品合格证","C．产品的有关图纸及技术资料","D．产品的技术性能、安全防护装置的说明","E．产品的发票"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_73"},{"id":74,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，注册执业人员未执行法律、法规和工程建设强制性标准的：（   ）","options":["A．责令停止执业三个月以上一年以下","B．情节严重的吊销执业资格证书，五年内不予注册","C．造成重大安全事故的，终身不予注册","D．构成犯罪的，依法追究刑事责任","E．降低资质等级"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_74"},{"id":75,"type":"multiple","stem":"根据《建筑业企业资质管理规定》，企业发生合并、分立、重组以及改制等事项，需承继原建筑业企业资质的，下列说法正确的是（   ）。","options":["A．企业合并的，可以继承合并前各方中较高的资质","B．企业分立的，按分立前各方较高的资质处理","C．企业改制的，可以继承原企业资质","D．企业分立的，应当申请重新核定建筑业企业资质等级","E．企业合并的，应当申请重新核定建筑业企业资质等级"],"answer":"DE","hasImage":false,"image":null,"globalId":"law_多选_75"},{"id":76,"type":"multiple","stem":"根据《建筑业企业资质管理规定》，建筑业企业资质分为（   ）。","options":["A．工程项目管理承包","B．施工总承包资质","C．专业承包资质","D．施工劳务资质","E．工程项目总承包"],"answer":"BCD","hasImage":false,"image":null,"globalId":"law_多选_76"},{"id":77,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，下列做法错误的是（   ）。","options":["A．总承包单位免费发放劳动保护用品","B．总承包单位向施工人员收取小部分费用更换已损坏或已到使用期限的劳动保护用品","C．分包单位和施工人员共同出资购买劳动保护用品","D．专业分包单位要求施工人员自行购买劳动保护用品","E．分包单位按规定要求为施工人员免费发放劳动保护用品"],"answer":"BCD","hasImage":false,"image":null,"globalId":"law_多选_77"},{"id":78,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，建筑业企业信用档案应当包括（   ）。","options":["A．企业基本情况","B．企业资质","C．企业业绩情况","D．企业合同履约情况","E．企业社会投诉和违法行为情况"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_78"},{"id":79,"type":"multiple","stem":"根据《房屋建筑和市政基础设施工程施工安全监督规定》，下列属于监督机构实施工程项目的施工安全监督措施的是（   ）。","options":["A．要求工程建设责任主体提供有关工程项目安全管理的文件和资料","B．进入工程项目施工现场进行安全监督抽查","C．发现安全隐患，责令整改或暂时停止施工","D．发现违法违规行为，按权限实施行政处罚或移交有关部门处理","E．向社会公布工程建设责任主体安全生产不良信息"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_79"},{"id":80,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，下列哪些说法是正确的的（   ）。","options":["A．施工作业人员有接受安全教育培训的权利","B．施工作业人员有按照工作岗位规定使用合格的劳动保护用品的权利","C．施工作业人员有拒绝违章指挥的权利","D．施工作业人员有拒绝使用不合格劳动保护用品","E．施工作业人员负有正确使用劳动保护用品的义务"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_80"},{"id":81,"type":"multiple","stem":"根据《建筑业企业资质管理规定》，有（   ）情形的，资质许可机关应当撤销建筑业企业资质。","options":["A．资质许可机关工作人员滥用职权、玩忽职守准予资质许可的","B．超越法定职权准予资质许可的","C．违反法定程序准予资质许可的","D．对不符合资质标准条件的申请企业准予资质许可的","E．依法可以撤销资质许可的其他情形。"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_81"},{"id":82,"type":"multiple","stem":"根据《建筑业企业资质管理规定》，下列做法不正确有（   ）。","options":["A．施工企业超越本企业资质等级或以其他企业的名义承揽工程，或允许其他企业或个人以本企业的名义承揽工程的","B．施工单位将承包的工程转包或违法分包的","C．施工企业与建设单位或企业之间相互串通投标，或以行贿等不正当手段谋取中标的","D．施工单位违反国家工程建设强制性标准施工的","E．施工企业恶意拖欠分包企业工程款或者劳务人员工资的"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_82"},{"id":83,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，安全生产监督管理部门的下述做法错误的是（   ）","options":["A．要求施工单位购买其认可的安全防护用品","B．向施工单位推荐安全设备产品目录","C．在安全设备检验时，仅收取检验成本费","D．在检查中发现事故隐患，责令立即排除","E．在检查中发现从业人员未戴安全帽，即要求停工整顿"],"answer":"ACE","hasImage":false,"image":null,"globalId":"law_多选_83"},{"id":84,"type":"multiple","stem":"根据《建设工程安全生产管理条例》以及相关的建筑施工安全规范，建筑施工中通常所说的“三宝”是指（   ）。","options":["A．安全帽","B．安全服","C．劳保鞋","D．安全带","E．安全网"],"answer":"ADE","hasImage":false,"image":null,"globalId":"law_多选_84"},{"id":85,"type":"multiple","stem":"根据《建筑施工人员个人劳动保护用品使用管理暂行规定》，下列属于建筑施工现场劳动保护用品的是（   ）。","options":["A．防护眼镜","B．防护手套","C．防尘（毒）口罩","D．安全（绝缘）鞋","E．安全标志"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_85"},{"id":86,"type":"multiple","stem":"根据《建筑起重机械安全监督管理规定》（建设部令第166号），有下列情形之一的建筑起重机械，不得出租、使用（   ）。","options":["A．属国家明令淘汰或者禁止使用的","B．结构件生锈的","C．经检验达不到安全技术标准规定的","D．没有完整安全技术档案的","E．没有齐全有效的安全保护装置的"],"answer":"ACDE","hasImage":false,"image":null,"globalId":"law_多选_86"},{"id":87,"type":"multiple","stem":"根据《建筑起重机械安全监督管理规定》（建设部令第166号），建筑起重机械有下列哪些情形之一的，出租单位或者自购建筑起重机械的使用单位应当予以报废，并向原备案机关办理注销手续。（   ）","options":["A．属国家明令淘汰或者禁止使用的","B．超过安全技术标准或者制造厂家规定的使用年限的","C．经检验达不到安全技术标准规定的","D．没有完整安全技术档案的","E．没有齐全有效的安全保护装置的"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_87"},{"id":88,"type":"multiple","stem":"根据《建筑起重机械安全监督管理规定》（建设部令第166号），建筑起重机械安装、拆卸工程档案应当包括以下（   ）资料","options":["A．安装、拆卸合同及安全协议书","B．安装、拆卸工程生产安全事故应急救援预案","C．安全施工技术交底的有关资料","D．安装工程验收资料","E．安装、拆卸工程专项施工方案"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_88"},{"id":89,"type":"multiple","stem":"根据《建筑起重机械安全监督管理规定》（建设部令第166号），建筑起重机械（   ）等特种作业人员应当经建设主管部门考核合格，并取得特种作业操作资格证书后，方可上岗作业。","options":["A．安装拆卸工","B．司索工","C．起重司机","D．其他作业人员","E．起重信号工"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_89"},{"id":90,"type":"multiple","stem":"根据《建筑起重机械安全监督管理规定》（建设部令第166号），建设主管部门履行安全监督检查职责时，有权采取下列措施（   ）。","options":["A．进入被检查单位和被检查单位的施工现场进行检查","B．要求被检查的单位提供有关建筑起重机械的文件和资料","C．对检查中发现的建筑起重机械生产安全事故隐患，责令立即排除","D．重大生产安全隐患排除前或排除过程中无法保证安全的，责令从危险区域撤出作业人员","E．重大生产安全隐患排除前或排除过程中无法保证安全的，责令暂时停止施工"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_90"},{"id":91,"type":"multiple","stem":"根据《建筑起重机械安全监督管理规定》（建设部令第166号），建筑起重机械安全技术档案应当包括（   ）","options":["A．购销合同、制造许可证、产品合格证、制造监督检验证明、安装使用说明书、备案证明等原始资料","B．历次安装验收资料","C．定期检验报告、定期自行检查记录、定期维护保养记录","D．维修和技术改造记录","E．运行故障和生产安全事故记录等"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_91"},{"id":92,"type":"multiple","stem":"根据《建筑起重机械安全监督管理规定》（建设部令第166号），建筑起重机械安装完成后由（   ）进行联合验收。","options":["A．建设单位","B．监理单位","C．施工总承包单位","D．使用单位","E．安装、拆除单位"],"answer":"BCDE","hasImage":false,"image":null,"globalId":"law_多选_92"},{"id":93,"type":"multiple","stem":"根据《建筑起重机械安全监督管理规定》（建设部令第166号），使用单位向建设主管部门申请办理建筑起重机械使用登记，应提交（   ）","options":["A．建筑起重机械安装验收资料","B．建筑起重机械安全管理制度","C．建筑起重机械使用说明书","D．项目安全管理机构","E．特种作业人员名单"],"answer":"ABE","hasImage":false,"image":null,"globalId":"law_多选_93"},{"id":94,"type":"multiple","stem":"根据《建筑起重机械安全监督管理规定》（建设部令第166号），建筑起重机械安装完毕后，安装单位应当按照安全技术标准及安装使用说明书的有关要求对建筑起重机械进行（   ）。","options":["A．自检","B．调试","C．维修保养","D．定期维护","E．试运转"],"answer":"ABE","hasImage":false,"image":null,"globalId":"law_多选_94"},{"id":95,"type":"multiple","stem":"根据《建筑起重机械安全监督管理规定》（建设部令第166号），以下哪些职责是建筑起重机械安装单位的职责（   ）","options":["A．编制起重机械安装、拆卸工程专项方案","B．按照安全技术标准及安装说明书等检查起重机械及现场施工条件","C．制定安装、拆卸工程生产安全事故应急救援预案","D．将起重机械安拆的相关资料报施工总承包、监理单位审核后，办理安拆告知","E．组织安全施工技术交底并签字确认"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_95"},{"id":96,"type":"multiple","stem":"根据《建筑起重机械安全监督管理规定》（建设部令第166号），以下哪些是建筑起重机械使用单位安全生产职责（   ）","options":["A．根据不同施工阶段、周围环境及季节、气候变化，对建筑起重机械采取相应安全防护措施","B．在建筑起重机械活动范围内设置明显安全警示标志，对集中作业区做好安全防护","C．对建筑起重机械操作人员证件进行审核并进行相应安全教育","D．将起重机械安拆的相关资料报施工总承包、监理单位审核后，办理安拆告知","E．指定专职设备管理员、专职安全生产管理人员进行现场监督检查"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_96"},{"id":97,"type":"multiple","stem":"根据《建筑施工企业安全生产许可证管理规定》，施工单位申请建筑施工企业安全生产许可证时，应具备建设行政主管部门或其他有关部门考核合格的人员包括（   ）","options":["A．主要负责人","B．项目负责人","C．特种作业人员","D．应急救援人员","E．专职安全生产管理人员"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_97"},{"id":98,"type":"multiple","stem":"根据《建筑施工企业安全生产许可证管理规定》，安全生产许可证颁发管理机关发现有下列情形之一的（   ），可以撤销已经颁发的安全生产许可证。","options":["A．违反法定程序颁发安全生产许可证的","B．对不具备安全生产条件的建筑施工企业颁发安全生产许可证的","C．超越法定职权颁发安全生产许可证的","D．安全生产许可证颁发管理机关工作人员滥用职权、玩忽职守颁发安全生产许可证的","E．建筑施工企业发生重大安全事故的"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_98"},{"id":99,"type":"multiple","stem":"根据《建筑施工企业安全生产许可证管理规定》，安全生产许可证颁发管理机关工作人员有下列行为之一的（   ），给予降级或者撤职的行政处分；构成犯罪的，依法追究刑事责任。","options":["A．向不符合本条例规定的安全生产条件的企业颁发安全生产许可证的","B．发现企业未依法取得安全生产许可证擅自从事生产活动，不依法处理的","C．发现取得安全生产许可证的企业不再具备本条例规定的安全生产条件，不依法处理的","D．接到对违反本条例规定行为的举报后，不及时处理的","E．在安全生产许可证颁发、管理和监督检查工作中，索取或者接受企业的财物，或者谋取其他利益的"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_99"},{"id":100,"type":"multiple","stem":"根据《建筑施工企业安全生产许可证管理规定》其适用范围为建筑施工企业，是指从事（   ）的新建、扩建、改建等有关活动的企业。","options":["A．土木工程","B．建筑工程","C．线路管道和设备安装工程","D．装修工程","E．电子工程"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_100"},{"id":101,"type":"multiple","stem":"根据《建筑施工企业安全生产许可证管理规定》，下列属于建筑施工企业申请安全许可证必须具备条件的是（   ）","options":["A．建立、健全安全生产责任制","B．保证本单位安全生产条件所需资金投入","C．依法参加工伤保险，为施工现场从事危险作业人员办理人身意外保险","D．制定生产安全事故应急救援预案","E．设置安全管理机构，按规定配备专职安全生产管理人员"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_101"},{"id":102,"type":"multiple","stem":"根据《房屋建筑和市政基础设施工程施工分包管理办法》，禁止将承包的工程进行转包，下列哪些属于转包行为（   ）","options":["A．分包人未在现场设立项目管理机构和派驻相应人员，未对工程的施工活动进行组织管理的","B．承包人不履行合同约定，将其承包的全部工程发包给他人","C．承包人将承包的部分工程以发包人名义发包给他人的","D．发包人将工程发包给不具备相应条件的施工企业的","E．承包人按照合同约定，将其承包的专业承包工程分包给具备资质的专业承包单位的"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_102"},{"id":103,"type":"multiple","stem":"根据《房屋建筑和市政基础设施工程施工分包管理办法》，下列行为，属于违法分包的是（   ）。","options":["A．分包工程发包人将专业工程分包给不具备相应资质条件的分包工程承包人的","B．分包工程发包人将劳务作业分包给不具备相应资质条件的分包工程承包人的","C．施工总承包合同中未有约定，经建设单位认可，总承包单位将承包工程中部分专业承包工程分包给他人的","D．施工总承包合同中未有约定，又未经建设单位认可的，总承包单位将承包工程中部分专业承包工程分包给他人的","E．施工总承包合同有约定，总承包单位按照约定将部分专业承包工程分包给他人的"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_103"},{"id":104,"type":"multiple","stem":"根据《房屋建筑和市政基础设施工程施工分包管理办法》，分包工程发包人设立的项目管理机构应当具有与承包工程的规模、技术复杂程度相适应的技术、经济管理人员。其中，（   ）必须是本单位的人员。","options":["A．项目负责人","B．技术负责人","C．安全管理人员","D．质量管理人员","E．项目核算负责人"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_104"},{"id":105,"type":"multiple","stem":"根据《房屋建筑和市政基础设施工程施工分包管理办法》，专业分包工程承包人应当将其分包工程的（   ）报分包工程发包人备案。","options":["A．设计图","B．施工组织设计","C．施工安全方案","D．技术交底","E．安全交底"],"answer":"BC","hasImage":false,"image":null,"globalId":"law_多选_105"},{"id":106,"type":"multiple","stem":"为了规范房屋建筑和市政基础设施工程施工分包活动，维护建筑市场秩序，保证（   ），制定《房屋建筑和市政基础设施工程施工分包管理办法》。","options":["A．工程进度","B．工程质量","C．施工安全","D．施工技术","E．施工工艺"],"answer":"BC","hasImage":false,"image":null,"globalId":"law_多选_106"},{"id":107,"type":"multiple","stem":"在《安全生产培训管理办法》中所称的生产经营单位从业人员，是指（   ）","options":["A．生产经营单位主要负责人","B．安全生产管理人员","C．其他人员","D．临时聘用人员","E．特种作业人员"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_107"},{"id":108,"type":"multiple","stem":"在《安全生产培训管理办法》中所称的从事安全生产相关人员是指（   ）","options":["A．从事安全教育培训工作的教师","B．危险化学品登记机构登记人员","C．承担安全评价、咨询、检验、检测人员","D．安全生产应急救援人员","E．注册安全工程师"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_108"},{"id":109,"type":"multiple","stem":"在《安全生产培训管理办法》中，安全培训目的是（   ）","options":["A．提高安全监管监察人员安全素质","B．提高生产经营单位从业人员安全素质","C．提高从事安全生产工作的相关人员的安全素质","D．提高政府行政管理人员的办事效率","E．以上都不是"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_109"},{"id":110,"type":"multiple","stem":"根据《安全生产培训管理办法》规定，生产经营单位应当（   ）","options":["A．建立安全培训管理制度","B．保障从业人员安全培训所需经费","C．对从业人员进行与其所从事岗位相应的安全教育培训","D．对调岗人员在进入新的岗位前进行专门的安全教育和培训","E．对采用新工艺、新技术、新设备、新材料的从业人员，进行专门的安全教育和培训"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_110"},{"id":111,"type":"multiple","stem":"根据《安全生产培训管理办法》，安全生产监督管理部门对生产经营单位的安全培训情况进行监督检查时，可以检查（   ）","options":["A．安全培训制度、年度培训计划、安全培训管理档案的制定和实施情况","B．安全培训经费投入和使用情况","C．主要负责人、安全生产管理人员、特种作业人员安全培训及持证上岗情况","D．转岗及应用新工艺、新技术、新设备、新材料前对从业人员安全培训情况","E．其他从业人员安全培训情况"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_111"},{"id":112,"type":"multiple","stem":"根据《安全生产培训管理办法》，生产经营单位从业人员应当具备那些安全生产知识和能力（   ）","options":["A．具备必要的安全生产知识","B．熟悉有关安全生产规章制度和安全操作规程","C．掌握本岗位的安全操作技能","D．知悉自身在安全生产方面的权利和义务","E．了解事故应急处理措施"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_112"},{"id":113,"type":"multiple","stem":"根据《安全生产培训管理办法》，下面哪些是班组级安全教育培训内容（   ）","options":["A．岗位安全操作规程","B．岗位之间工作衔接配合的安全与职业卫生事项","C．有关事故案例","D．法律法规知识","E．安全防护装置、个人防护用品的使用及维护"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_113"},{"id":114,"type":"multiple","stem":"根据《生产经营单位安全培训规定》，安全教育培训档案包含以下哪些内容（   ）","options":["A．培训的时间","B．培训的内容","C．参加人员","D．考核结果","E．组织过程"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_114"},{"id":115,"type":"multiple","stem":"按照《生产经营单位安全培训规定》，生产经营单位存在以下哪些行为之一的，可以处5万元以下罚款（   ）。","options":["A．煤矿、危险化学品等生产经营单位主要负责人和安全管理人员未按照规定经考核合格的","B．未按照规定对从业人员进行安全生产教育和培训的","C．特种作业人员未取得特种作业人员操作资格证上岗作业的","D．未对被派遣劳动者、实习学生进行安全生产教育和培训","E．未如实记录安全生产教育和培训情况的"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_115"},{"id":116,"type":"multiple","stem":"按照《生产经营单位安全培训规定》，生产经营单位主要负责人安全培训应当包括以下哪些内容（   ）","options":["A．国家安全生产方针、政策和有关安全生产法律法规、规章及标准","B．安全生产管理基本知识、安全生产技术、安全生产专业知识","C．重大危险源管理、重大事故防范的有关规定","D．典型事故和应急救援案例","E．伤亡事故统计、报告及职业危害的调查处理方法"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_116"},{"id":117,"type":"multiple","stem":"根据《生产安全事故隐患排查治理暂行规定》，生产经营单位应当定期组织（   ）和其他相关人员排查本单位的事故隐患。","options":["A．企业主要负责人","B．安全生产管理人员","C．工程技术人员","D．项目部管理人员","E．财务人员"],"answer":"BC","hasImage":false,"image":null,"globalId":"law_多选_117"},{"id":118,"type":"multiple","stem":"根据《生产安全事故隐患排查治理暂行规定》，生产经营单位将（   ）发包、出租的，应当与承包、承租单位签订安全生产管理协议。","options":["A．生产经营项目","B．场所","C．装备","D．物资","E．设备"],"answer":"ABE","hasImage":false,"image":null,"globalId":"law_多选_118"},{"id":119,"type":"multiple","stem":"根据《生产安全事故隐患排查治理暂行规定》，重大事故隐患治理方案应当包括以下哪些内容（   ）","options":["A．治理的目标、任务和时限","B．采取的方法、措施和要求","C．负责治理的机构和人员","D．经费、物资的落实","E．安全措施和应急预案"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_119"},{"id":120,"type":"multiple","stem":"根据《生产安全事故隐患排查治理暂行规定》，生产经营单位在事故隐患排查治理过程中，应该做到以下哪些方面（   ）","options":["A．应当采取相应的安全防范措施防止事故发生。","B．无法保证安全的，应当从危险区域撤出作业人员","C．设置警戒标志，暂时停产停业或停止使用","D．对暂时难以停产停业的相关设施、设备，加强维护保养，防止事故发生","E．疏散可能危及的其他相关人员"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_120"},{"id":121,"type":"multiple","stem":"根据《生产安全事故隐患排查治理暂行规定》，生产经营单位在事故隐患排查治理过程中，无法保证安全的（   ）","options":["A．应当从危险区域撤出作业人员","B．疏散可能危及的其他相关人员","C．设置警戒标志，暂时停产停业或停止使用","D．对暂时难以停产停业的相关设施、设备，加强维护保养，防止事故发生","E．克服困难，抓紧时间抢工期"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_121"},{"id":122,"type":"multiple","stem":"根据《生产安全事故隐患排查治理暂行规定》，生产经营单位对重大事故隐患，应当及时向安全监管监察部门报告，报告内容应当包括（   ）","options":["A．检查时间及人员","B．检查过程及问题","C．隐患的现状及产生原因","D．隐患的危害程度及整改的难易程度","E．隐患的治理方案"],"answer":"CDE","hasImage":false,"image":null,"globalId":"law_多选_122"},{"id":123,"type":"multiple","stem":"根据《生产安全事故隐患排查治理暂行规定》，以下哪些属于安全生产违法行为行政处罚（   ）","options":["A．警告、罚款","B．责令停产停业整顿","C．没收违法所得","D．暂扣或吊销有关许可证、暂扣或撤销有关职业资格、岗位证书","E．拘留"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_123"},{"id":124,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，以下关于行政处罚正确的有（   ）","options":["A．由负责安全生产监督管理的部门决定","B．予以关闭的行政处罚由负责安全生产监督管理的部门报请县级以上人民政府按照国务院规定的权限决定","C．给予拘留的行政处罚由公安机关依照治安管理处罚条例的规定决定","D．有关法律、行政法规对行政处罚的决定机关另有规定的，依照其规定","E．由国家安全部门决定"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_124"},{"id":125,"type":"multiple","stem":"根据《安全生产违法行为行政处罚办法》，对安全生产违法行的行政处罚，应当遵循（   ）的原则。","options":["A．公平","B．公正","C．公开","D．从重","E．公立"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_125"},{"id":126,"type":"multiple","stem":"根据《安全生产违法行为行政处罚办法》，以下哪些行政处罚由发证机关决定（   ）","options":["A．暂扣有关许可证","B．吊销有关许可证","C．责令停产停业整顿、责令停产停业","D．暂停有关执业资格、岗位证书","E．撤销有关执业资格、岗位证书"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_126"},{"id":127,"type":"multiple","stem":"根据《安全生产违法行为行政处罚办法》，对生产经营单位可以从重处罚的情形有哪些（   ）","options":["A．危及公共安全或者其他生产经营单位安全，责令限期改正，逾期未改的","B．拒不整改或整改不力，违法行为呈持续状态的","C．拒绝、阻碍或者以暴力威胁行政执法人员的","D．主动消除或者减轻安全生产违法行为后果的","E．一年内因同一违法行为受到两次及以上行政处罚的"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_127"},{"id":128,"type":"multiple","stem":"根据《安全生产违法行为行政处罚办法》，生产经营单位与从业人员订立协议，以下说法正确的是（   ）","options":["A．免除其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议无效","B．减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议无效","C．免除其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议有效","D．减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议有效","E．免除或者减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议有效与否视情况而定"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_128"},{"id":129,"type":"multiple","stem":"根据《安全生产违法行为行政处罚办法》，对严重安全生产违法行为可以给予的行政处罚包括（   ）","options":["A．责令停产停业整顿","B．责令停止建设","C．吊销有关许可证","D．撤销有关执业资格或岗位证书","E．没有违法所得"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_129"},{"id":130,"type":"multiple","stem":"根据《安全生产违法行为行政处罚办法》，行政处罚决定书应当载明事项包括以下哪些内容（   ）","options":["A．当事人的姓名或者名称、地址或者住址","B．违法事实和证据","C．行政处罚的种类和依据","D．行政处罚的履行方式和期限","E．行政处罚的金额和支付方式"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_130"},{"id":131,"type":"multiple","stem":"根据《建筑工程施工许可管理办法》，申请领取施工许可证，应当具备下列条件（   ）。","options":["A．已经办理建筑工程用地审批手续","B．在城市规划区的建筑工程，已经取得规划许可证","C．有保证工程质量和安全的具体措施","D．有满足施工需要的施工图纸及技术资料","E．法律、行政法规规定的其他条件"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_131"},{"id":132,"type":"multiple","stem":"根据《建设项目安全设施“三同时”监督管理办法》，建设项目安全设施，是指生产经营单位在生产经营活动中用于预防生产安全事故的（   ）的总称。","options":["A．设备","B．设施","C．装置","D．构（建筑物）","E．其他技术措施"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_132"},{"id":133,"type":"multiple","stem":"根据《生产安全事故应急预案管理办法》，应急预案的管理原则有哪些（   ）","options":["A．属地为主","B．分级负责","C．分类指导","D．综合协调","E．动态管理"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_133"},{"id":134,"type":"multiple","stem":"根据《生产安全事故应急预案管理办法》，生产经营单位主要负责人负责组织编制和实施本单位的应急预案,并对应急预案的（   ）和（   ）负责。","options":["A．完整性","B．适用性","C．真实性","D．可行性","E．实用性"],"answer":"CE","hasImage":false,"image":null,"globalId":"law_多选_134"},{"id":135,"type":"multiple","stem":"根据《生产安全事故应急预案管理办法》，应急预案的编制应当遵循（   ）的原则,以应急处置为核心,明确应急职责、规范应急程序、细化保障措施。","options":["A．依法依规","B．风险预判","C．以人为本","D．符合实际","E．注重实效"],"answer":"ACDE","hasImage":false,"image":null,"globalId":"law_多选_135"},{"id":136,"type":"multiple","stem":"根据《生产安全事故应急预案管理办法》，编制应急预案前，应进行事故风险辨识、评估，事故风险辨识、评估的主要内容（   ）。","options":["A．针对不同事故种类及特点,识别存在的危险危害因素","B．分析事故可能产生的直接后果以及次生、衍生后果","C．评估各种后果的危害程度和影响范围","D．对施工方案的有效性进行分析","E．提出防范和控制事故风险措施的过程"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_136"},{"id":137,"type":"multiple","stem":"根据《生产安全事故应急预案管理办法》，生产经营单位组织开展的应急培训，应该包括以下哪些内容（   ）","options":["A．应急预案","B．应急知识","C．自救互救","D．避险逃生技能","E．岗位职责"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_137"},{"id":138,"type":"multiple","stem":"根据《生产安全事故应急预案管理办法》，有下列情形（   ）的,应急预案应当及时修订并归档。","options":["A．应急指挥机构及其职责发生调整的","B．重要应急资源发生一般变化的","C．安全生产面临的风险发生重大变化的","D．在应急演练和事故应急救援中发现需要修订预案的重大问题的","E．编制单位认为应当修订的其他情况"],"answer":"ACDE","hasImage":false,"image":null,"globalId":"law_多选_138"},{"id":139,"type":"multiple","stem":"根据《生产安全事故应急预案管理办法》，生产经营单位应当按照应急预案的规定,落实（   ）,建立应急物资、装备配备及其使用档案,并对应急物资、装备进行定期检测和维护,使其处于适用状态。","options":["A．救援场所","B．应急救援队伍","C．应急指挥体系","D．应急物资及装备","E．应急演练"],"answer":"BCD","hasImage":false,"image":null,"globalId":"law_多选_139"},{"id":140,"type":"multiple","stem":"根据《生产安全事故应急预案管理办法》，综合应急救援预案应当包含以下哪些内容（   ）","options":["A．应急预案体系、应急组织机构及职责","B．事故风险描述","C．预警及信息报告","D．应急响应","E．保障措施"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_140"},{"id":141,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），“安管人员”申请安全生产考核,应当满足以下哪些条件（   ）","options":["A．具备相应文化程度","B．专业技术职称和一定安全生产工作经历","C．与企业确定劳动关系","D．经企业年度安全生产教育培训考核","E．工作表现优异，获得安全生产荣誉"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_141"},{"id":142,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），建筑施工“安管人员”安全生产知识考核包含以下哪些内容（   ）","options":["A．建筑施工安全生产法律法规","B．建筑施工安全生产标准规范","C．建筑施工安全生产规章制度","D．建筑施工安全管理基本理论","E．企业安全管理制度"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_142"},{"id":143,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），建筑施工“安管人员”安全生产管理能力考核包含以下哪些内容（   ）","options":["A．建立和落实安全生产管理制度","B．发现和消除安全事故隐患","C．辨识和监控危险性较大的分部分项工程","D．建筑施工安全管理基本理论","E．报告和处置生产安全事故"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_143"},{"id":144,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），主要负责人对本企业安全生产工作全面负责，应当（   ），落实安全生产责任。","options":["A．建立健全企业安全生产管理体系","B．设置安全生产管理机构","C．配备专职安全生产管理人员","D．保证安全生产投入","E．定期参加本企业安全生产检查"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_144"},{"id":145,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），企业主要负责人应当与项目负责人签订安全生产责任书，确定项目（   ），以及企业为项目提供的安全管理和技术保障措施。","options":["A．安全生产考核目标","B．安全生产奖惩措施","C．安全生产管理人员","D．安全生产投入","E．安全管理制度"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_145"},{"id":146,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），建筑施工企业主要负责人、项目负责人未按规定履行安全生产管理职责，县级以上住房城乡建设主管部门可以进行哪些处罚（   ）","options":["A．责令限期改正","B．逾期未改正的，责令停业整顿","C．造成生产安全事故或其他严重后果的，按照《生产安全事故报告和调查处理条例》，依法暂扣或者吊销安全生产考核合格证书","D．暂扣建筑施工企业安全生产许可证","E．构成犯罪的，依法追究刑事责任。"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_146"},{"id":147,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），项目负责人对本项目安全生产管理全面负责，应当履行以下哪些安全生产职责（   ）","options":["A．建立项目安全生产管理体系","B．明确项目管理人员安全职责","C．落实安全生产管理制度","D．确保项目安全生产费用有效使用","E．保证项目施工质量符合规定"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_147"},{"id":148,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定实施意见》规定，专职安全生产管理人员分为（   ）三类。","options":["A．机械","B．设备","C．土建","D．安装","E．综合"],"answer":"ACE","hasImage":false,"image":null,"globalId":"law_多选_148"},{"id":149,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），申请项目负责人安全生产考核，应当具备下列哪些条件（   ）","options":["A．具有工程师以上技术职称","B．取得相应注册执业资格","C．与所在企业确立劳动关系","D．经所在企业年度安全生产教育培训合格","E．有一定的现场管理经验"],"answer":"BCD","hasImage":false,"image":null,"globalId":"law_多选_149"},{"id":150,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），机械类专职安全生产管理人员及综合类专职安全生产管理人员安全生产管理能力考核内容必须包括（   ）等。","options":["A．攀爬塔吊","B．起重机械隐患识别","C．附着式升降脚手架现场管理","D．现场消防隐患识别","E．土石方机械管理"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_150"},{"id":151,"type":"multiple","stem":"根据《建筑施工企业安全生产管理机构设置及专职安全生产管理人员配备办法》，特级、一级施工总承包资质序列企业和一级专业承包资质序列企业宜设置专职安全总监。安全总监应满足以下哪些要求（   ）","options":["A．通过安全生产知识及管理能力的考核","B．具备中级及以上注册安全工程师执业资格","C．取得建筑施工企业主要负责人安全生产考核合格证书","D．在本行业领域内从事安全管理工作满3年","E．具备初级及以上注册安全工程师执业资格"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_151"},{"id":152,"type":"multiple","stem":"根据《建筑施工企业安全生产管理机构设置及专职安全生产管理人员配备办法》，以下说法正确的是（   ）","options":["A．企业主要负责人应当熟悉房屋市政工程生产安全重大事故隐患判定标准，每月对企业重大事故隐患排查整改情况至少开展1次专项检查","B．企业主要负责人应当每半年至少组织开展1次应急预案演练；企业安全总监应当协助做好组织实施工作","C．企业主要负责人应当根据项目进度，带班检查企业在建项目的安全生产工作，每年检查时间不少于企业全年施工时间的25%","D．企业主要负责人应当与项目负责人签订安全生产责任书，确定项目安全生产考核目标、奖惩措施，以及企业为项目提供的安全管理和技术保障措施","E．企业必须设置企业安全总监，并明确安全生产职责"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_152"},{"id":153,"type":"multiple","stem":"根据《危险性较大的分部分项工程安全管理规定》，危大工程专项方案实施前，应当履行哪些审批手续（   ）","options":["A．由施工单位技术负责人审核签字","B．加盖单位公章","C．由监理工程师审查签字","D．由总监理工程师审查签字","E．加盖执业印章"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_153"},{"id":154,"type":"multiple","stem":"根据《危险性较大的分部分项工程安全管理规定》，对于按规定需要验收的危险性较大的分部分项工程，施工单位、监理单位应当组织有关人员进行验收。验收合格的，经（   ）签字后，方可进入下一道工序。","options":["A．施工单位项目技术负责人","B．项目总监理工程师","C．项目专项方案编制人","D．项目专职安全生产管理人员","E．项目专业监理工程师"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_154"},{"id":155,"type":"multiple","stem":"根据《危险性较大的分部分项工程安全管理规定》，施工单位危大工程安全管理档案应包含以下哪些内容（   ）","options":["A．专项施工方案及审核","B．专家论证","C．交底","D．现场检查","E．验收及整改"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_155"},{"id":156,"type":"multiple","stem":"根据《危险性较大的分部分项工程安全管理规定》，监理单位发现施工单位未按照危大工程专项施工方案施工，有严重隐患要求其暂停施工，施工单位拒不停止施工的，监理单位应当及时报告（   ）","options":["A．建设单位","B．监测单位","C．设计单位","D．工程所在地住房城乡建设主管部门","E．勘察单位"],"answer":"AD","hasImage":false,"image":null,"globalId":"law_多选_156"},{"id":157,"type":"multiple","stem":"根据《危险性较大的分部分项工程安全管理规定》，以下哪些人员应当参加超过一定规模危险性较大分部分项工程专家论证（   ）","options":["A．专家","B．建设单位项目负责人","C．有关勘察、设计单位项目技术负责人","D．监理单位项目总监理工程师及专业监理工程师","E．总承包单位和分包单位技术负责人、项目负责人等"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_157"},{"id":158,"type":"multiple","stem":"根据《危险性较大的分部分项工程安全管理规定》，危大工程专项施工方案，专家论证的主要内容应当包括（   ）。","options":["A．专项施工方案内容是否完整、可行","B．专项施工方案计算书和验算依据、施工图是否符合有关标准规范","C．专项施工方案是否满足现场实际情况，并能够确保施工安全","D．专项施工方案是否经济合理","E．专项施工方案是否经总监理工程师审查同意"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_158"},{"id":159,"type":"multiple","stem":"根据《危险性较大的分部分项工程安全管理规定》，监理单位在项目危大工程施工期间，应当履行以下哪些职责（   ）","options":["A．对施工过程实施专项巡视检查","B．对超过一定规模危大工程实行旁站监理","C．发现施工单位未按照专项方案施工的，要求其整改","D．情节严重的，要求其暂停施工，并及时报告建设单位","E．施工单位拒不整改的，应当及时报告建设单位和工程所在地住房和城乡建设有关部门"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_159"},{"id":160,"type":"multiple","stem":"根据《陕西省房屋建筑和市政基础设施工程危险性较大的分部分项工程安全管理实施细则》规定，对于按照规定需要验收的危大工程，施工单位、监理单位应当组织相关人员进行验收。验收人员应当包括（   ）","options":["A．建设单位项目负责人","B．监理单位项目总监理工程师及专业监理工程师；","C．有关勘察、设计和监测单位项目技术负责人；","D．总承包单位和分包单位技术负责人或授权委派的专业技术人员、项目负责人、项目技术负责人、专项施工方案编制人员、项目专职安全生产管理人员及相关人员；","E．不少于2名原专项方案论证专家。"],"answer":"BCDE","hasImage":false,"image":null,"globalId":"law_多选_160"},{"id":161,"type":"multiple","stem":"根据《危险性较大的分部分项工程安全管理规定》，高大模板支撑系统是指建设工程施工现场混凝土构件模板支撑（   ）的模板支撑系统。","options":["A．搭设高度8m及以上","B．或搭设跨度18m及以上","C．或施工总荷载15kN/m²及以上","D．集中线荷载20kN/m及以上","E．集中荷载大于15kN及以上"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_161"},{"id":162,"type":"multiple","stem":"根据《危险性较大的分部分项工程安全管理规定》，以下哪些分部分项工程属于危险性较大分部分项工程（   ）","options":["A．开挖深度虽未超过3m，但地质条件复杂的基坑的土方开挖、支护、降水工程","B．采用非常规起重设备、方法，且单件起吊重量在8kN及以上的起重吊装工程","C．附着式升降脚手架工程、异型脚手架工程","D．采用矿山法、盾构法、顶管法施工的隧道、洞室工程","E．装配式建筑混凝土预制构件安装工程"],"answer":"ACDE","hasImage":false,"image":null,"globalId":"law_多选_162"},{"id":163,"type":"multiple","stem":"根据《危险性较大的分部分项工程安全管理规定》，以下哪些分部分项工程属于超过一定规模危险性较大分部分项工程（   ）","options":["A．开挖深度超过5m（含5m）的基坑（槽）的土方开挖、支护、降水工程","B．施工总荷载15kN/m²及以上，或集中线荷载（设计值）20kN/m及以上混凝土模板支撑工程","C．承受单点集中荷载5kN及以上钢结构满堂支撑体系","D．采用非常规起重设备、方法，且单件起吊重量在100kN及以上的起重吊装工程","E．分段架体搭设高度18m及以上的悬挑式脚手架工程"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_163"},{"id":164,"type":"multiple","stem":"根据《危险性较大的分部分项工程安全管理规定》，高大模板支撑系统的拆除作业必须（   ）。","options":["A．自上而下逐层进行","B．严禁上下层同时拆除作业","C．先里后外","D．先轻后重","E．分段拆除的高度不应大于两层"],"answer":"ABE","hasImage":false,"image":null,"globalId":"law_多选_164"},{"id":165,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），建筑施工企业有（   ）行为之一的，由县级以上人民政府住房城乡建设主管部门责令限期改正；逾期未改正的，责令停业整顿，并处2万元以下的罚款；导致不具备《安全生产许可证条例》规定的安全生产条件的，应当依法暂扣或者吊销安全生产许可证：","options":["A．未按规定设立安全生产管理机构的","B．未按规定配备专职安全生产管理人员的","C．危险性较大的分部分项工程施工时未安排专职安全生产管理人员现场监督的","D．“安管人员”未取得安全生产考核合格证书的","E．未制定企业安全生产责任制的"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_165"},{"id":166,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），项目负责人应当按规定实施项目安全生产管理，（   ）；发生事故时，应当按规定及时报告并开展现场救援。","options":["A．建立项目安全生产管理体系","B．落实安全主体责任","C．监控危险性较大分部分项工程","D．及时排查处理施工现场安全事故隐患","E．明确项目管理人员安全职责"],"answer":"CD","hasImage":false,"image":null,"globalId":"law_多选_166"},{"id":167,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），安全资格证书（   ）。","options":["A．不得出借给其他机构或者个人","B．不得出租给其他机构或者个人","C．可出借、出租给其他机构","D．可出借、出租给个人","E．经批准可出借、出租给其他机构和个人"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_167"},{"id":168,"type":"multiple","stem":"根据《房屋建筑和市政基础设施工程施工分包管理办法》，以下有关分包工程发包人和承包人之间的说法正确的有（   ）","options":["A．承包人就施工现场安全向发包人负责","B．承包人按照合同约定对其承包工程向发包人负责","C．发包人对施工现场安全负责，对承包人的安全生产进行管理","D．发包人和承包人就分包工程对建设单位承担连带责任","E．发包人和承包人之间是独立的施工单位，各自承担责任"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_168"},{"id":169,"type":"multiple","stem":"违反《房屋建筑和市政基础设施工程施工分包管理办法》规定，转包、违法分包或者允许他人以本企业名义承揽工程的，接受转包和用他人名义承揽工程的，按（   ）的规定予以处罚。","options":["A．中华人民共和国建筑法","B．中华人民共和国安全法","C．中华人民共和国招投标法","D．建设工程质量管理条例","E．中华人民共和国行政处罚办法"],"answer":"ACD","hasImage":false,"image":null,"globalId":"law_多选_169"},{"id":170,"type":"multiple","stem":"违反《建筑起重机械安全管理规定》，施工总承包单位未履行以下哪些安全职责（   ），由县级以上地方人民政府建设主管部门责令限期改正，予以警告，并处罚款5000元以上3万元以下。","options":["A．向安装单位提供拟安装设备位置的基础施工资料，确保建筑起重机械进场安装、拆卸所需的施工条件","B．审核安装单位、使用单位的资质证书、安全生产许可证和特种作业人员的特种作业操作资格证书；","C．审核安装单位制定的建筑起重机械安装、拆卸工程专项施工方案和生产安全事故应急救援预案；","D．审核使用单位制定的建筑起重机械生产安全事故应急救援预案；","E．施工现场有多台塔式起重机作业时，应当组织制定并实施防止塔式起重机相互碰撞的安全措施。"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_170"},{"id":171,"type":"multiple","stem":"根据《安全生产违法行为行政处罚办法》，生产经营单位及其有关人员有下列（   ）情形的，应当依法从轻或者减轻行政处罚。","options":["A．已满14周岁不满20周岁的公民实施安全生产违法行为的","B．主动消除或者减轻安全生产违法行为危害后果的","C．配合安全监管监察部门查处安全生产违法行为，有立功表现的","D．主动投案，向安全监管监察部门如实交待自己的违法行为的","E．安全生产违法行为轻微并及时纠正，没有造成危害后果的"],"answer":"BCDE","hasImage":false,"image":null,"globalId":"law_多选_171"},{"id":172,"type":"multiple","stem":"根据《建筑施工企业主要负责人、项目负责人和专职安全生产管理人员安全生产管理规定》（住建部令第17号），土建类专职安全生产管理人员可以从事除（   ）等安全生产管理工作以外的安全生产管理工作。","options":["A．土木工程","B．起重机械","C．土石方机械","D．桩工机械","E．挖掘机械"],"answer":"BCD","hasImage":false,"image":null,"globalId":"law_多选_172"},{"id":173,"type":"multiple","stem":"《中华人民共和国安全生产法》三次修订时间分别为（   ）","options":["A．2009年8月27日","B．2014年8月31日","C．2017年8月27日","D．2021年6月10日","E．2021年9月1日"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_173"},{"id":174,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，安全生产工作实行（   ）。","options":["A．管生产经营必须管安全","B．管企业党政工团","C．管行业必须管安全","D．管行政必须管安全","E．管业务必须管安全"],"answer":"ACE","hasImage":false,"image":null,"globalId":"law_多选_174"},{"id":175,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位必须加大对安全生产（   ）的投入保障力度，改善安全生产条件。","options":["A．资金","B．物资","C．技术","D．人员","E．经费"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_175"},{"id":176,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位必须加强安全生产（   ）建设。","options":["A．技能化","B．标准化","C．科技化","D．信息化","E．人性化"],"answer":"BD","hasImage":false,"image":null,"globalId":"law_多选_176"},{"id":177,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位必须构建（   ）和（   ）双重预防机制，健全风险防范化解机制，提高安全生产水平，确保安全生产。","options":["A．隐患排查治理","B．安全隐患排查","C．风险分级管控","D．安全风险分级管控","E．施工人员教育培训管控"],"answer":"AD","hasImage":false,"image":null,"globalId":"law_多选_177"},{"id":178,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，县级以上地方各级人民政府应当按照安全风险管控要求，进行产业规划和空间布局，并对（   ）的生产经营单位实施重大安全风险联防联控。","options":["A．位置相邻","B．来往频繁","C．业务相关","D．业态相似","E．行业相近"],"answer":"ADE","hasImage":false,"image":null,"globalId":"law_多选_178"},{"id":179,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，（   ）以及开发区、工业园区、港区、风景区等应当明确负责安全生产监督管理的有关工作机构及其职责，加强安全生产监管力量建设，按照职责对本行政区域或者管理区域内生产经营单位安全生产状况进行监督检查。","options":["A．省级人民政府","B．市级人民政府","C．县级人民政府","D．乡镇人民政府","E．街道办事处"],"answer":"CE","hasImage":false,"image":null,"globalId":"law_多选_179"},{"id":180,"type":"multiple","stem":"国务院（   ）等有关部门依照《中华人民共和国安全生产法》和其他有关法律、行政法规的规定，在各自的职责范围内对有关行业、领域的安全生产工作实施监督管理。","options":["A．交通运输","B．住房和城乡建设","C．水利","D．民航","E．海运"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_180"},{"id":181,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位必须执行依法制定的保障安全生产的（   ）。","options":["A．行业标准","B．行业规范","C．国家标准","D．国家规范","E．地方标准"],"answer":"AC","hasImage":false,"image":null,"globalId":"law_多选_181"},{"id":182,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，国务院标准化行政主管部门负责安全生产强制性国家标准的（   ）工作。","options":["A．立项","B．编号","C．实施","D．授权批准发布","E．对外通报"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_182"},{"id":183,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，（   ）依据法定职责对安全生产强制性国家标准的实施进行监督检查。","options":["A．国务院标准化行政主管部门","B．省标准化行政主管部门","C．国务院有关部门","D．省有关部门","E．施工总承包企业"],"answer":"AC","hasImage":false,"image":null,"globalId":"law_多选_183"},{"id":184,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，国家对在改善安全生产条件、防止生产安全事故、参加抢险救护等方面取得显著成绩的（   ），给予奖励。","options":["A．集体","B．单位","C．团队","D．个人","E．组织"],"answer":"BD","hasImage":false,"image":null,"globalId":"law_多选_184"},{"id":185,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位的主要负责人对本单位安全生产工作负有下列（   ）职责。","options":["A．组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制，督促、检查本单位的安全生产工作，及时消除生产安全事故隐患","B．组织制定并实施本单位的生产安全事故应急救援预案","C．及时、如实报告生产安全事故","D．建立健全并落实本单位全员安全生产责任制，加强安全生产标准化建设","E．只对自己对职责范围内的安全生产工作负责。"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_185"},{"id":186,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位的全员安全生产责任制应当明确各岗位的（   ）等内容。","options":["A．责任人员","B．权利与义务","C．责任范围","D．考核标准","E．具体安全职责"],"answer":"ACD","hasImage":false,"image":null,"globalId":"law_多选_186"},{"id":187,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位应当具备的安全生产条件所必需的资金投入，由生产经营单位的（   ）或者个人经营的投资人予以保证，并对由于安全生产所必需的资金投入不足导致的后果承担责任。","options":["A．决策机构","B．工会组织","C．单位安全负责人","D．主要负责人","E．负责生产的生产经理"],"answer":"AD","hasImage":false,"image":null,"globalId":"law_多选_187"},{"id":188,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位的安全生产管理机构以及安全生产管理人员履行下列（   ）职责。","options":["A．组织开展危险源辨识和评估，督促落实本单位重大危险源的安全管理措施","B．组织或者参与本单位应急救援演练","C．制止和纠正违章指挥、强令冒险作业、违反操作规程的行为","D．检查本单位的安全生产状况，及时排查生产安全事故隐患，并负责进行安全隐患整改","E．组织开展危大工程辨识和评估，督促落实本单位危大工程的安全管理措施"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_188"},{"id":189,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位的（   ）必须具备与本单位所从事的生产经营活动相应的安全生产知识和管理能力。","options":["A．安全主要负责人","B．主要负责人","C．安全生产管理人员","D．安全质量管理人员","E．生产主要负责人"],"answer":"BC","hasImage":false,"image":null,"globalId":"law_多选_189"},{"id":190,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，危险物品的生产、经营、储存、装卸单位以及矿山、金属冶炼、建筑施工、运输单位的（   ），应当由主管的负有安全生产监督管理职责的部门对其安全生产知识和管理能力考核合格。","options":["A．安全主要负责人","B．主要负责人","C．安全生产管理人员","D．安全质量管理人员","E．生产主要负责人"],"answer":"BC","hasImage":false,"image":null,"globalId":"law_多选_190"},{"id":191,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位应当在有较大危险因素的（   ）上，设置明显的安全警示标志。","options":["A．生产经营场所","B．设计图纸","C．设施","D．设备","E．生活区"],"answer":"ACD","hasImage":false,"image":null,"globalId":"law_多选_191"},{"id":192,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位对重大危险源应当登记建档，进行定期（   ），并制定应急预案，告知从业人员和相关人员在紧急情况下应当采取的应急措施。","options":["A．检测","B．评估","C．监控","D．报验","E．审核审批"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_192"},{"id":193,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位应当按照国家有关规定将本单位（   ）报有关地方人民政府应急管理部门和有关部门备案。有关地方人民政府应急管理部门和有关部门应当通过相关信息系统实现信息共享。","options":["A．重大危险源","B．危大工程清单","C．有关安全措施","D．应急措施","E．专项方案"],"answer":"ACD","hasImage":false,"image":null,"globalId":"law_多选_193"},{"id":194,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，两个以上生产经营单位在同一作业区域内进行生产经营活动，可能危及对方生产安全的，应当签订安全生产管理协议，明确各自的（   ），并指定专职安全生产管理人员进行安全检查与协调。","options":["A．应当采取的安全措施","B．安全生产管理职责","C．安全岗位管理职责","D．安全预防措施","E．安全协调管理措施"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_194"},{"id":195,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位不得因从业人员对本单位安全生产工作提出批评、检举、控告或者拒绝违章指挥、强令冒险作业而（   ）。","options":["A．解除与其订立的劳动合同","B．降低其工资","C．降低其福利等待遇","D．进行相应奖励","E．进行处罚"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_195"},{"id":196,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，从业人员发现直接危及人身安全的紧急情况时，（   ）。","options":["A．无权停止作业，必须先汇报经同意后方可停止作业","B．有权停止作业","C．无权在采取可能的应急措施后自行撤离作业场所","D．有权在采取可能的应急措施后撤离作业场所","E．立即实施救援"],"answer":"BD","hasImage":false,"image":null,"globalId":"law_多选_196"},{"id":197,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，从业人员应当接受（   ），掌握本职工作所需的安全生产知识，提高安全生产技能，增强事故预防和应急处理能力。","options":["A．安全生产教育","B．安全技术交底","C．岗位教育","D．培训","E．方案交底"],"answer":"AD","hasImage":false,"image":null,"globalId":"law_多选_197"},{"id":198,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，从业人员发现事故隐患或者其他不安全因素，应当立即向（   ）报告；接到报告的人员应当及时予以处理。","options":["A．企业安全管理部门","B．现场安全生产管理人员","C．单位生产经理","D．本单位负责人","E．部门经理"],"answer":"BD","hasImage":false,"image":null,"globalId":"law_多选_198"},{"id":199,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，应急管理部门和其他负有安全生产监督管理职责的部门依法开展安全生产行政执法工作，对生产经营单位执行有关安全生产的法律、法规和国家标准或者行业标准的情况进行监督检查，行使以下（   ）职权。","options":["A．进入生产经营单位进行检查，调阅有关资料，向有关单位和人员了解情况","B．对检查中发现的安全生产违法行为，当场予以纠正或者要求限期改正","C．重大事故隐患排除后，经审查同意，方可恢复生产经营和使用","D．监督检查不得影响被检查单位的正常生产经营活动","E．为了检查方便，检查部门可以随时让企业停止生产经营活动"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_199"},{"id":200,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位对负有安全生产监督管理职责的部门的监督检查人员依法履行监督检查职责（   ）。","options":["A．应当进行适当的配合","B．应当予以配合","C．不得拒绝、阻挠","D．对于涉及到企业保密方面的提问可以拒绝回答","E．应当无条件配合"],"answer":"BC","hasImage":false,"image":null,"globalId":"law_多选_200"},{"id":201,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，负有安全生产监督管理职责的部门依法对存在重大事故隐患的生产经营单位作出停产停业、停止施工、停止使用相关设施或者设备的决定，生产经营单位（   ）。","options":["A．可以在确保安全的情况下边生产边整顿","B．应当根据企业实际进行处置","C．应当依法执行","D．及时消除事故隐患","E．可以根据生产情况进行执行"],"answer":"CD","hasImage":false,"image":null,"globalId":"law_多选_201"},{"id":202,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，新闻、出版、广播、电影、电视等单位有（   ）的义务，有对违反安全生产法律、法规的行为进行（   ）的权利。","options":["A．进行安全生产公益宣传教育","B．进行安全生产全民教育","C．整改监督","D．舆论监督","E．批评检举"],"answer":"AD","hasImage":false,"image":null,"globalId":"law_多选_202"},{"id":203,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位发生生产安全事故后，事故现场有关人员应当立即报告本单位负责人。单位负责人接到事故报告后，应当迅速采取有效措施，组织抢救，防止事故扩大，减少人员伤亡和财产损失，并按照国家有关规定立即如实报告当地负有安全生产监督管理职责的部门，不得（   ）。","options":["A．故意破坏事故现场","B．隐瞒不报","C．毁灭有关证据","D．谎报或者迟报","E．事故人员家属"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_203"},{"id":204,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，负有安全生产监督管理职责的部门的工作人员，有下列行为之一的，给予降级或者撤职的处分；构成犯罪的，依照刑法有关规定追究刑事责任（   ）","options":["A．发现未依法取得批准、验收的单位擅自从事有关活动或者接到举报后不予取缔或者不依法予以处理的","B．在监督检查中发现重大事故隐患，不依法及时处理的","C．对不符合法定安全生产条件的涉及安全生产的事项予以批准或者验收通过的","D．对已经依法取得批准的单位不履行监督管理职责，发现其不再具备安全生产条件而不撤销原批准或者发现安全生产违法行为不予查处的","E．在监督检查中发现重大事故隐患，处理不到位的"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_204"},{"id":205,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位的主要负责人未履行本法规定的安全生产管理职责，导致发生生产安全事故的，由应急管理部门依照下列规定处以罚款","options":["A．发生一般事故的，处上一年年收入百分之四十的罚款","B．发生较大事故的，处上一年年收入百分之六十的罚款","C．发生重大事故的，处上一年年收入百分之八十的罚款","D．发生特别重大事故的，处上一年年收入百分之八十的罚款","E．发生特别重大事故的，处上一年年收入百分之一百的罚款"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_205"},{"id":206,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位未与承包单位、承租单位（   ）的，责令限期改正，处五万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以下的罚款；逾期未改正的，责令停产停业整顿。","options":["A．签订专门的安全生产管理协议","B．签订专业承包合同","C．签订联合安全生产合同","D．未对承包单位、承租单位的安全生产统一协调、管理","E．未在承包合同、租赁合同中明确各自的安全生产管理职责"],"answer":"ADE","hasImage":false,"image":null,"globalId":"law_多选_206"},{"id":207,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目的施工单位倒卖、出租、出借、挂靠或者以其他形式非法转让施工资质的（   ）。","options":["A．处违法所得二倍以上五倍以下的罚款","B．没收违法所得","C．责令停产停业整顿","D．吊销资质证书","E．吊销安全生产许可证书"],"answer":"BCD","hasImage":false,"image":null,"globalId":"law_多选_207"},{"id":208,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，两个以上生产经营单位在同一作业区域内进行可能危及对方安全生产的生产经营活动，（   ）的，责令限期改正，处五万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以下的罚款；逾期未改正的，责令停产停业。","options":["A．未签订安全生产管理协议","B．未签订专业承包合同协议","C．未指定专职生产技术管理人员进行检查与协调","D．未指定专职安全生产管理人员进行安全检查与协调","E．未组织联合生产管理机构"],"answer":"AD","hasImage":false,"image":null,"globalId":"law_多选_208"},{"id":209,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位的从业人员（   ）的，由生产经营单位给予批评教育，依照有关规章制度给予处分；构成犯罪的，依照刑法有关规定追究刑事责任。","options":["A．不服从管理","B．不落实岗位安全责任","C．违反操作规程","D．违反安全生产规章制度","E．不享受年薪假"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_209"},{"id":210,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位的主要负责人在本单位发生生产安全事故时，（   ）的，给予降级、撤职的处分，并由应急管理部门处上一年年收入百分之六十至百分之一百的罚款；对逃匿的处十五日以下拘留；构成犯罪的，依照刑法有关规定追究刑事责任。","options":["A．在事故调查处理期间逃匿","B．不立即组织抢救","C．在事故调查处理期间擅离职守","D．在事故调查处理期间不予以配合","E．严保企业秘密"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_210"},{"id":211,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位的主要负责人对生产安全事故（   ）的，给予降级、撤职的处分，并由应急管理部门处上一年年收入百分之六十至百分之一百的罚款；对逃匿的处十五日以下拘留；构成犯罪的，依照刑法有关规定追究刑事责任。","options":["A．漏报","B．隐瞒不报","C．谎报","D．迟报","E．不是由专职安全生产管理人员上报"],"answer":"BCD","hasImage":false,"image":null,"globalId":"law_多选_211"},{"id":212,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，有关地方人民政府、负有安全生产监督管理职责的部门，对生产安全事故（   ）的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依照刑法有关规定追究刑事责任。","options":["A．漏报","B．隐瞒不报","C．谎报","D．迟报","E．不是由专职安全生产管理人员上报"],"answer":"BCD","hasImage":false,"image":null,"globalId":"law_多选_212"},{"id":213,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位存在下列（   ）情形之一的，负有安全生产监督管理职责的部门应当提请地方人民政府予以关闭，有关部门应当依法吊销其有关证照。生产经营单位主要负责人五年内不得担任任何生产经营单位的主要负责人；情节严重的，终身不得担任本行业生产经营单位的主要负责人","options":["A．存在重大事故隐患，一百八十日内三次或者一年内四次受到《中华人民共和国安全生产法》规定的行政处罚的","B．不具备法律、行政法规和国家标准或者行业标准规定的安全生产条件，导致发生重大、特别重大生产安全事故的","C．经停产停业整顿，仍不具备法律、行政法规和国家标准或者行业标准规定的安全生产条件的","D．拒不执行负有安全生产监督管理职责的部门作出的停产停业整顿决定的","E．造成企业重大经济损失"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_213"},{"id":214,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，危险物品，是指（   ）等能够危及人身安全和财产安全的物品。","options":["A．有毒有害物品","B．易燃易爆物品","C．危险化学品","D．放射性物品","E．污染性物品"],"answer":"BCD","hasImage":false,"image":null,"globalId":"law_多选_214"},{"id":215,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，国务院应急管理部门和其他负有安全生产监督管理职责的部门应当根据各自的职责分工，制定相关行业、领域（   ）标准。","options":["A．危大工程的辨识","B．重大危险源的辨识","C．重大事故危害程度的判定","D．重大事故隐患的判定","E．安全生产"],"answer":"BD","hasImage":false,"image":null,"globalId":"law_多选_215"},{"id":216,"type":"multiple","stem":"为了加强建设工程安全生产监督管理，保障人民群众生命和财产安全，根据（   ），制定《建设工程安全生产管理条例》。","options":["A．《中华人民共和国建筑法》","B．《中华人民共和国城市规划法》","C．《中华人民共和国安全生产法》","D．《中华人民共和国建设工程质量管理条例》","E．《中华人民共和国建设工程勘察设计管理条例》"],"answer":"AC","hasImage":false,"image":null,"globalId":"law_多选_216"},{"id":217,"type":"multiple","stem":"某施工单位项目部在城市街区进行深基坑开挖工程，依照《中华人民共和国安全生产法》规定，以下表述正确的是（   ）。","options":["A．施工单位应当登记建档","B．施工单位应当制定应急预案","C．施工单位作的应急措施应经安全监督部门批准","D．施工单位作的应急措施应经安全监督部门备案","E．施工单位应当定期检测、评估、监控"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_217"},{"id":218,"type":"multiple","stem":"根据《危险性较大的分部分项工程安全管理规定》，下列属于达到一定规模的危险性较大的分部分项工程的是（   ）。","options":["A．基坑支护与降水工程","B．土方开挖工程","C．起重吊装工程","D．临时用电工程","E．脚手架工程"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_218"},{"id":219,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，使用承租的机械设备和施工机具及配件的，由（   ）共同进行验收。验收合格的方可使用。","options":["A．施工总承包单位","B．分包单位","C．建设单位","D．出租单位","E．安装单位"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_219"},{"id":220,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，施工单位的（   ）应当经建设行政主管部门或者其他有关部门考核合格后方可任职。","options":["A．法定代表人","B．主要负责人","C．项目负责人","D．专职安全生产管理人员","E．兼职安全员"],"answer":"BCD","hasImage":false,"image":null,"globalId":"law_多选_220"},{"id":221,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位采用（   ）或者使用新设备，必须了解、掌握其安全技术特性，采取有效的安全防护措施，并对从业人员进行专门的安全生产教育和培训 。","options":["A．新技术","B．新工艺","C．新方法","D．新材料","E．新程序"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_221"},{"id":222,"type":"multiple","stem":"根据《建设工程安全生产管理条例》规定，县级以上人民政府在履行安全监督检查职责时，对于发现的重大安全事故隐患在排除前或者排除过程中无法保证安全的，采取的必要措施不包括（   ）。","options":["A．继续施工","B．更换施工队伍","C．责令从危险区域撤出作业人员或暂时停止施工","D．责令施工单位主要负责人作出检查","E．责令建设单位主要负责人作出检查"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_222"},{"id":223,"type":"multiple","stem":"根据《建设工程安全生产管理条例》规定，施工单位应当向作业人员提供安全防护用具和安全防护服装，并书面告知（   ）。","options":["A．操作规程","B．违章操作的危害","C．使用方法","D．使用要领","E．赔付数量"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_223"},{"id":224,"type":"multiple","stem":"根据《建设工程安全生产管理条例》规定，施工单位对列入建设工程概算的安全作业环境及安全施工措施所需费用，应当用于（   ），不得挪作他用。","options":["A．施工安全防护用具及设施的采购和更新","B．安全施工措施的落实","C．安全生产条件的改善","D．特殊作业人员津贴","E．办公费用"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_224"},{"id":225,"type":"multiple","stem":"根据《建设工程安全生产管理条例》规定，下列（   ）情况应由有关部门按有关规定追究有关领导和直接责任者的责任，并给予必要的行政、经济处罚。","options":["A．对事故隐瞒不报、谎报","B．对事故故意迟延不报","C．故意破坏事故现场","D．无正当理由拒绝接受调查","E．拒绝提供有关情况和资料"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_225"},{"id":226,"type":"multiple","stem":"根据《建设工程安全生产管理条例》规定，，施工单位应当在安全生产方面做好如下几项工作（   ）。","options":["A．建立健全安全生产责任制度和安全生产教育培训制度","B．制定安全生产规章制度和操作规程","C．保证本单位安全生产条件所需资金的投入","D．对所承担的建设工程进行定期和专项安全检查，并做好安全检查记录","E．提高管理者素质"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_226"},{"id":227,"type":"multiple","stem":"根据《建设工程安全生产管理条例》规定，施工单位应当在施工现场建立消防安全责任制度，确定消防安全责任人，制定用火、用电、使用易燃易爆材料等各项消防安全管理制度、操作规程，（   ），并在施工现场人口处设置明显标志。","options":["A．设置消防通道","B．配备消防水源","C．配备消防设施","D．配备灭火器材","E．请消防队员驻防"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_227"},{"id":228,"type":"multiple","stem":"根据《建设工程安全生产管理条例》规定，施工单位在使用施工（   ）等自升式架设设施前，应当组织有关单位进行验收，也可以委托具有相应资质的检验检测机构进行验收。","options":["A．悬挑脚手架","B．起重机械","C．整体提升脚手架","D．混凝土输送泵","E．模板"],"answer":"BCE","hasImage":false,"image":null,"globalId":"law_多选_228"},{"id":229,"type":"multiple","stem":"根据《建设工程安全生产管理条例》规定，使用承租的机械设备和施工机具及配件，由施工（   ）共同进行验收。","options":["A．主管部门","B．总承包单位","C．分包单位","D．出租单位","E．安装单位"],"answer":"BCDE","hasImage":false,"image":null,"globalId":"law_多选_229"},{"id":230,"type":"multiple","stem":"根据《建设工程安全生产管理条例》规定，建设工程施工前，施工单位负责项目管理的技术人员应当对有关安全施工的技术要求向施工（   ）作出详细说明，并由双方签字确认。","options":["A．施工队伍负责人","B．施工队伍安全员","C．作业班组","D．现场安全员","E．作业人员"],"answer":"CE","hasImage":false,"image":null,"globalId":"law_多选_230"},{"id":231,"type":"multiple","stem":"根据《建设工程安全生产管理条例》规定，施工单位应当遵守有关环境保护法律、法规的规定，在施工现场采取措施，防止或者减少（   ）、振动和施工照明对人和环境的危害和污染。","options":["A．粉尘","B．废气废水","C．建筑材料","D．固体废物","E．噪声"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_231"},{"id":232,"type":"multiple","stem":"根据《建设工程安全生产管理条例》规定，建筑施工企业应当为施工现场（   ）的人员，在施工活动过程中发生的人身意外伤亡事故提供保障，办理建筑意外伤害保险、支付保险费。","options":["A．建设单位","B．监理","C．全部","D．施工作业","E．管理"],"answer":"DE","hasImage":false,"image":null,"globalId":"law_多选_232"},{"id":233,"type":"multiple","stem":"根据《建筑施工安全检查标准》JGJ 59-2011，施工现场坑、井、沟和各种（   ）周围，都要指定专人设置围栏或盖板和安全标志，夜间要设红灯示警；各种防护设施、警告标志，未经施工负责人批准不得移动和拆除。","options":["A．混凝土搅拌站","B．孔洞","C．易燃易爆场所","D．变压器","E．钢筋切断机"],"answer":"BCD","hasImage":false,"image":null,"globalId":"law_多选_233"},{"id":234,"type":"multiple","stem":"根据《安全生产许可证条例》，企业取得安全生产许可证，应当具备下列安全生产条件，其中包括（   ）。","options":["A．安全投入符合安全生产要求；","B．设置安全生产管理机构，配备专职或兼职安全生产管理人员；","C．主要负责人和安全生产管理人员经考核合格；","D．特种作业人员经有关业务主管部门考核合格，取得特种作业操作资格证书；","E．从业人员经安全生产教育和培训合格；"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_234"},{"id":235,"type":"multiple","stem":"根据《安全生产许可证条例》，安全生产许可证颁发管理机关工作人员有下列（   ）行为之一的，给予降级或者撤职的行政处分；构成犯罪的，依法追究刑事责任。","options":["A．向符合本条例规定的安全生产条件的企业颁发安全生产许可证的","B．发现企业未依法取得安全生产许可证擅自从事生产活动，不依法处理的","C．发现取得安全生产许可证的企业不再具备本条例规定的安全生产条件，不依法处理的","D．接到对违反本条例规定行为的举报后，不及时处理的","E．在安全生产许可证颁发、管理和监督检查工作中，索取或者接受企业的财物，或者谋取其他利益的"],"answer":"BCDE","hasImage":false,"image":null,"globalId":"law_多选_235"},{"id":236,"type":"multiple","stem":"根据《安全生产许可证条例》，企业不得（   ）、（   ）安全生产许可证或者使用（   ）的安全生产许可证。","options":["A．转让","B．冒用","C．替换","D．伪造","E．假冒"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_236"},{"id":237,"type":"multiple","stem":"根据《安全生产许可证条例》，安全生产许可证颁发管理机关工作人员在安全生产许可证（   ）工作中，不得索取或者接受企业的财物，不得谋取其他利益。","options":["A．下发","B．颁发","C．管理","D．监督检查","E．延期"],"answer":"BCD","hasImage":false,"image":null,"globalId":"law_多选_237"},{"id":238,"type":"multiple","stem":"根据《工伤保险条例》规定，列入专家库的医疗卫生专业技术人员应当具备（   ）。","options":["A．具有医疗卫生高级专业技术职务任职资格","B．掌握劳动能力鉴定的相关知识","C．具有良好的职业品德","D．具有执业医生证","E．具有医师资格证"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_238"},{"id":239,"type":"multiple","stem":"《工伤保险条例》的适用范围为（   ）。","options":["A．中华人民共和国境内的企业、事业单位、社会团体","B．民办非企业单位","C．基金会、律师事务所、会计师事务所","D．有雇工的个体工商户","E．央企"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_239"},{"id":240,"type":"multiple","stem":"根据《工伤保险条例》规定，工伤保险基金的构成分为（   ）。","options":["A．用人单位缴纳的工伤保险费","B．工伤保险基金的利息","C．依法纳入工伤保险基金的其他资金","D．个人缴纳的工伤保险","E．用人单位和个人按比例缴纳的工伤保险金"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_240"},{"id":241,"type":"multiple","stem":"根据《工伤保险条例》规定，职工存在（   ），应当认定为工伤。","options":["A．在工作时间和工作场所内，因工作原因受到事故伤害的","B．工作时间前后在工作场所内，从事与工作有关的预备性或者收尾性工作受到事故伤害的;","C．在工作时间和工作场所内，因履行工作职责受到暴力等意外伤害的","D．患职业病的以及在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的","E．因工外出期间，由于工作原因受到伤害或者发生事故下落不明的以及法律、行政法规规定应当认定为工伤的其他情形"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_241"},{"id":242,"type":"multiple","stem":"根据《工伤保险条例》规定，职工存在以下（   ），视同工伤。","options":["A．在工作时间和工作岗位，突发疾病死亡或者在48小时之内经抢救无效死亡的","B．在抢险救灾等维护国家利益、公共利益活动中受到伤害的","C．职工原在军队服役，因战、因公负伤致残，已取得革命伤残军人证，到用人单位后旧伤复发的","D．因履行工作职责受到暴力等意外伤害的","E．在上下班途中，由本人负主要责任的交通事故"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_242"},{"id":243,"type":"multiple","stem":"根据《工伤保险条例》规定，存在以下（   ），不得认定为工伤或者视同工伤。","options":["A．故意犯罪的;","B．醉酒或者吸毒的","C．自残或者自杀的","D．患有职业病的","E．有职业病史的"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_243"},{"id":244,"type":"multiple","stem":"根据《工伤保险条例》规定，上下班途中出现以下（   ），应当认定为工伤。","options":["A．因履行工作职责受到暴力等意外伤害的","B．受到非本人主要责任的交通事故","C．受到城市轨道交通、客运轮渡、火车事故伤害的","D．因工外出期间，由于工作原因受到伤害或者发生事故下落不明的","E．受到本人主要责任的交通事故"],"answer":"BC","hasImage":false,"image":null,"globalId":"law_多选_244"},{"id":245,"type":"multiple","stem":"根据《工伤保险条例》规定，提出工伤认定申请应该提交的资料有（   ）。","options":["A．工伤认定申请表","B．与用人单位存在劳动关系（包括事实劳动关系）、人事关系的证明材料","C．医疗诊断证明或者职业病诊断证明书(或者职业病诊断鉴定书)","D．劳动仲裁结果","E．工作考勤表"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_245"},{"id":246,"type":"multiple","stem":"根据《工伤保险条例》规定，用人单位（   ）的，承继单位应当承担原用人单位的工伤保险责任;原用人单位已经参加工伤保险的，承继单位应当到当地经办机构办理工伤保险变更登记。","options":["A．分立","B．合并","C．兼并","D．转让","E．撤资"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_246"},{"id":247,"type":"multiple","stem":"根据《工伤保险条例》规定，存在以下（   ），有关单位或者个人可以依法申请行政复议，也可以依法向人民法院提起行政诉讼。","options":["A．申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定申请不予受理的决定不服的;","B．申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定结论不服的","C．用人单位对经办机构确定的单位缴费费率不服的","D．签订服务协议的医疗机构、辅助器具配置机构认为经办机构未履行有关协议或者规定的;","E．工伤职工或者其近亲属对经办机构核定的工伤保险待遇有异议的"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_247"},{"id":248,"type":"multiple","stem":"根据《工伤保险条例》规定，社会保险行政部门工作人员存在（   ），依法给予处分;情节严重，构成犯罪的，依法追究刑事责任.","options":["A．无正当理由不受理工伤认定申请，或者弄虚作假将不符合工伤条件的人员认定为工伤职工的","B．未妥善保管申请工伤认定的证据材料，致使有关证据灭失的","C．收受当事人财物的","D．阻挠工伤鉴定的","E．拖延办理的"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_248"},{"id":249,"type":"multiple","stem":"根据《工伤保险条例》规定，（   ）有权提出劳动能力复查鉴定申请。","options":["A．工伤职工近亲属","B．工伤职工所在单位","C．工伤保险经办机构","D．工伤职工","E．工伤鉴定部门"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_249"},{"id":250,"type":"multiple","stem":"根据《工伤保险条例》规定，职工工亡，其近亲属可以享受（   ）工伤保险待遇。","options":["A．丧葬补助金","B．供养亲属抚恤金","C．一次性工亡补助金","D．姻亲抚恤金","E．一次性工伤补助金"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_250"},{"id":251,"type":"multiple","stem":"根据《工伤保险条例》规定，工伤职工存在（   ），停止享受工伤保险待遇。","options":["A．丧失享受待遇条件的","B．拒不接受劳动能力鉴定的","C．上报虚假劳动能力证明的","D．拒绝治疗的","E．阻挠工伤鉴定的"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_251"},{"id":252,"type":"multiple","stem":"根据《工伤保险条例》规定，社会保险行政部门等部门制定工伤保险的政策、标准，应当征求（   ）的意见。","options":["A．工会组织","B．用人单位代表","C．劳动者","D．职工代表","E．工伤鉴定委员会"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_252"},{"id":253,"type":"multiple","stem":"根据《工伤保险条例》规定，生活自理障碍分为（   ）。","options":["A．生活完全不能自理","B．生活大部分不能自理","C．生活部分不能自理","D．生活能够部分自理","E．生活需要专人照管"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_253"},{"id":254,"type":"multiple","stem":"根据《工伤保险条例》规定，治疗工伤所需费用符合（   ）可从工伤保险基金支付。","options":["A．工伤保险诊疗项目目录","B．工伤保险药品目录","C．工伤保险住院服务标准","D．工伤保险治疗标准","E．治疗工伤外疾病的"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_254"},{"id":255,"type":"multiple","stem":"根据《工伤保险条例》规定，经办机构具体承办工伤保险事务，应该履行（   ）职责。","options":["A．根据省、自治区、直辖市人民政府规定，征收工伤保险费","B．核查用人单位的工资总额和职工人数，办理工伤保险登记，并负责保存用人单位缴费和职工享受工伤保险待遇情况的记录","C．进行工伤保险的调查、统计","D．按照规定管理工伤保险基金的支出","E．按照规定核定工伤保险待遇以及为工伤职工或者其近亲属免费提供咨询服务"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_255"},{"id":256,"type":"multiple","stem":"根据《工伤保险条例》规定（   ）单位的职工受到事故伤害或者患职业病的，由该单位向伤残职工或者死亡职工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇。","options":["A．无营业执照","B．未经依法登记、备案的单位","C．被依法吊销营业执照","D．撤销登记、备案","E．无安全生产许可证"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_256"},{"id":257,"type":"multiple","stem":"根据《工伤保险条例》规定（   ）因工作遭受事故伤害或者患职业病的，由所在单位支付费用。","options":["A．公务员","B．参照公务员法管理的事业单位、社会团体的作业人员","C．事业单位","D．建设单位","E．施工单位"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_257"},{"id":258,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，生产经营单位主要负责人在本单位发生重大生产安全事故时（   ）。","options":["A．不立即组织抢救或者在事故调查处理期间擅离职守或者逃匿的，给予降职、撤职的处分，对逃匿的，由公安机关处15日以下拘留","B．与从业人员订立合同减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议无效","C．不立即组织抢救或者在事故调查处理期间擅离职守或者逃匿的，有关部门应当依法吊销其有关证照","D．不立即组织抢救或者在事故调查处理期间擅离职守或者逃匿的，给予拘留的行政处罚，由公安机关依照治安管理处罚条例的规定决定","E．予以罚款"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_258"},{"id":259,"type":"multiple","stem":"制定《生产安全事故报告和调查处理条例》是为了（   ）","options":["A．规范生产安全事故的报告","B．规范生产安全事故的调查处理","C．落实生产安全事故责任追究制度","D．防止和减少生产安全事故制定","E．加强政府行政主管部门对安全生产事故报告和调查处理"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_259"},{"id":260,"type":"multiple","stem":"（   ）的报告和调查处理不适用《生产安全事故报告和调查处理条例》。","options":["A．环境污染事故","B．核设施事故","C．国防科研生产事故","D．生产经营活动中发生的造成人身伤亡","E．工程质量事故"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_260"},{"id":261,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，事故报告应当及时、准确、完整，任何单位和个人对事故不得（   ）","options":["A．迟报","B．漏报","C．谎报","D．瞒报","E．通报"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_261"},{"id":262,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，报告事故应当包括（   ）","options":["A．事故发生单位概况","B．事故发生的时间、地点以及事故现场情况","C．事故的简要经过","D．已经采取的措施","E．事故处理结果"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_262"},{"id":263,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，因抢救人员、防止事故扩大以及疏通交通等原因，需要移动事故现场物件的，应当（   ）。","options":["A．做出标志","B．绘制现场简图并做出书面记录","C．直接移动","D．妥善保存现场重要痕迹、物证","E．等待处理"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_263"},{"id":264,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，事故调查组应（   ）。","options":["A．查明事故发生的经过、原因、人员伤亡情况及直接经济损失","B．认定事故的性质和事故责任","C．提出对事故责任者的处理建议","D．总结事故教训，提出防范和整改措施","E．向事故发生单位直接下达处理通知"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_264"},{"id":265,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，事故调查组成员在事故调查工作中应当（   ）。","options":["A．诚信公正、恪尽职守","B．遵守事故调查组的纪律","C．保守事故调查的秘密","D．可随时发布有关事故的信息","E．可直接发布事故处理结果"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_265"},{"id":266,"type":"multiple","stem":"根据《生产安全事故应急条例》，有下列（   ）情形的，生产安全事故应急救援预案制定单位应当及时修订相关预案。","options":["A．制定预案所依据的法律、法规、规章、标准发生重大变化","B．应急指挥机构及其职责发生调整","C．安全生产面临的风险发生重大变化","D．在预案演练或者应急救援中发现需要修订预案的重大问题","E．重要应急资源发生重大变化"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_266"},{"id":267,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，应急救援队伍的应急救援人员应当具备必要的（   ）。","options":["A．专业知识","B．技能","C．身体素质","D．心理素质","E．社会责任"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_267"},{"id":268,"type":"multiple","stem":"根据《生产安全事故应急条例》，下列（   ）单位应当建立应急值班制度，配备应急值班人员。","options":["A．县级以上人民政府及其负有安全生产监督管理职责的部门","B．危险物品的生产、经营、储存、运输单位","C．矿山、金属冶炼、城市轨道交通运营、建筑施工单位","D．施工班组","E．应急救援队伍"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_268"},{"id":269,"type":"multiple","stem":"根据《生产安全事故应急条例》，县级以上人民政府应当依照本条例的规定,严格履行职责,（   ）地完成事故调查处理工作。","options":["A．按时","B．及时","C．准确","D．精准","E．马上"],"answer":"BC","hasImage":false,"image":null,"globalId":"law_多选_269"},{"id":270,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，任何（   ）不得阻挠和干涉对事故的报告和依法调查处理。","options":["A．单位","B．劳务班组","C．个人","D．法人","E．劳务公司"],"answer":"AC","hasImage":false,"image":null,"globalId":"law_多选_270"},{"id":271,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，（   ）逐级上报至国务院安全生产监督管理部门和负有安全生产监督管理职责的有关部门。","options":["A．特别重大事故","B．重大事故","C．较大事故","D．一般事故","E．责任事故"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_271"},{"id":272,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，较大事故逐级上报至（   ）人民政府安全生产监督管理部门和负有安全生产监督管理职责的有关部门。","options":["A．省","B．自治区","C．直辖市","D．县级","E．区级"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_272"},{"id":273,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，（   ）分别由事故发生地省级人民政府、设区的市级人民政府、县级人民政府负责调查。","options":["A．重大事故","B．较大事故","C．一般事故","D．特别重大事故","E．责任事故"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_273"},{"id":274,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，（   ）应当建立值班制度,并向社会公布值班电话,受理事故报告和举报。","options":["A．生产经营单位","B．安全生产监督管理部门","C．负有安全生产监督管理职责的有关部门","D．法人","E．个人"],"answer":"BC","hasImage":false,"image":null,"globalId":"law_多选_274"},{"id":275,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，（   ）,负责事故调查的人民政府应当自收到事故调查报告之日起15日内做出批复。","options":["A．重大事故","B．较大事故","C．一般事故","D．特别重大事故","E．责任事故"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_275"},{"id":276,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，事故调查组履行下列（   ）职责。","options":["A．查明事故发生的经过、原因、人员伤亡情况及直接经济损失","B．认定事故的性质和事故责任","C．提出对事故责任者的处理建议","D．总结事故教训,提出防范和整改措施","E．提交事故调查报告"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_276"},{"id":277,"type":"multiple","stem":"根据《生产安全事故报告和调查处理条例》，事故调查报告应当包括下列哪些内容（   ）","options":["A．事故发生单位概况","B．事故发生经过和事故救援情况","C．事故造成的人员伤亡和直接经济损失","D．事故发生的原因和事故性质","E．事故责任的认定以及对事故责任者的处理建议"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_277"},{"id":278,"type":"multiple","stem":"根据《生产安全事故应急条例》，县级以上人民政府应急管理部门（   ）、（   ）本级人民政府其他负有安全生产监督管理职责的部门和下级人民政府的生产安全事故应急工作。","options":["A．指导","B．协调","C．治理","D．服务","E．监督"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_278"},{"id":279,"type":"multiple","stem":"根据《生产安全事故应急条例》，生产安全事故应急救援预案应当具有（   ）、（   ）和（   ）。","options":["A．可操作性","B．针对性","C．科学性","D．精准性","E．预测性"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_279"},{"id":280,"type":"multiple","stem":"根据《生产安全事故应急条例》，国家（   ）和（   ）生产经营单位和其他社会力量建立提供社会化应急救援服务的应急救援队伍。","options":["A．鼓励","B．支持","C．规定","D．强制","E．要求"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_280"},{"id":281,"type":"multiple","stem":"根据《生产安全事故应急条例》，（   ）或者（   ）等规模较小的生产经营单位，可以不建立应急救援队伍。","options":["A．小型企业","B．微型企业","C．建筑施工单位","D．矿山","E．劳务班组"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_281"},{"id":282,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，应急救援队伍应当配备必要的应急救援（   ）和（   ），并定期组织训练。","options":["A．装备","B．物资","C．食物","D．水","E．车辆"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_282"},{"id":283,"type":"multiple","stem":"为了保证建设工程质量，加强建设工程安全生产监督管理，保护人民生命和财产安全，根据（   ）等法律、行政法规，结合本省实际，制定《陕西省建设工程质量和安全生产管理条例》。","options":["A．《中华人民共和国建筑法》","B．《建设工程质量管理条例》","C．《建设工程安全生产管理条例》","D．《安全生产许可证条例》","E．《生产安全事故应急条例》"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_283"},{"id":284,"type":"multiple","stem":"根据《陕西省建设工程质量和安全生产管理条例》规定，建设单位不得将建设工程的（ ）发包给不同的施工单位","options":["A．地基基础分部","B．主体结构分部","C．外墙工程分部","D．屋面工程分部","E．装修工程分部"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_284"},{"id":285,"type":"multiple","stem":"根据《陕西省建设工程质量和安全生产管理条例》规定，施工单位应当按照设计文件和技术标准组织施工，对建设工程的施工质量和安全生产负责，并履行下列（   ）义务。","options":["A．建立健全质量责任制、安全生产责任制和重大危险源监管、安全生产教育培训等制度","B．确定项目负责人、技术负责人、专业工长和项目质量员、安全员、试验员、测量员、资料员、材料员等施工管理人员","C．严格工序管理和施工质量检验，做好质量和安全生产相关资料的收集整理","D．承建主体结构的施工单位在施工期间对建设工程沉降进行观测","E．制定重大事故应急预案"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_285"},{"id":286,"type":"multiple","stem":"根据《陕西省建设工程质量和安全生产管理条例》规定，施工单位项目负责人在建设工程施工前，对（   ），应当向施工作业人员作出详细说明。","options":["A．项目工程概况","B．工程质量和安全施工的有关技术要求","C．工程进度要求","D．重大危险源","E．技术标准"],"answer":"BD","hasImage":false,"image":null,"globalId":"law_多选_286"},{"id":287,"type":"multiple","stem":"根据《陕西省建设工程质量和安全生产管理条例》规定，施工单位应当将建设单位给付的安全文明施工措施费，用于（   ）等，不得挪作他用。","options":["A．施工安全防护用品（具）以及设施的采购和更新","B．安全施工措施的落实","C．安全生产条件的改善","D．专职安全管理人员工资","E．“三同时”安全设施费用支出"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_287"},{"id":288,"type":"multiple","stem":"根据《陕西省建设工程质量和安全生产管理条例》规定，（   ）应当对进场主要建筑材料、建筑构配件和设备进行联合验收，并对建筑材料、建筑构配件和设备的验收承担责任。","options":["A．施工单位的项目负责人","B．施工单位的项目技术负责人","C．施工单位的项目材料员","D．施工单位的项目工长","E．监理单位的监理工程师"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_288"},{"id":289,"type":"multiple","stem":"根据《建设工程安全生产管理条例》，施工单位应当在施工组织设计中编制（   ）。对达到一定规模的危险性较大的分部分项工程编制专项施工方案，并附具安全验算结果，经施工单位技术负责人、总监理工程师签字后实施。对超过一定规模的危险性较大的分部分项工程，还应组织专家进行论证、审查。","options":["A．安全技术措施","B．施工现场临时用电方案","C．工程质量保证措施","D．工程进度计划","E．安全管理制度"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_289"},{"id":290,"type":"multiple","stem":"根据《陕西省建设工程质量和安全生产管理条例》规定，建设工程质量安全监督机构对建设工程质量和安全生产实施监督管理的主要职责是（   ）","options":["A．宣传贯彻有关建设工程质量和安全方面的法律、法规","B．监督检查建设工程的质量和安全生产工作","C．接受并即时处理建设工程质量和安全生产方面的举报和投诉","D．查处违反建设工程质量和安全法律、法规的行为","E．法律、法规规定的其他职责"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_290"},{"id":291,"type":"multiple","stem":"根据《陕西省建设工程质量和安全生产管理条例》规定，建设工程质量安全监督机构履行监督检查职责时，可以采取下列措施（   ）","options":["A．进入施工现场进行检查","B．要求被检查单位提供建设工程质量和安全生产的文件和资料","C．纠正违反建设工程质量和安全生产要求的行为，并依法予以处理","D．责令被检查单位立即排除建设工程质量和安全生产事故隐患，重大安全事故隐患排除前或者排除过程中无法保证安全的，责令从危险区域内撤出作业人员或者暂时停止施工","E．法律、法规授权可以采取的其他措施"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_291"},{"id":292,"type":"multiple","stem":"根据《陕西省建设工程质量和安全生产管理条例》不适用（   ）建筑工程。","options":["A．军事建设工程","B．抢险救灾工程","C．农民自建低层住宅","D．民航机场工程","E．其他临时性建筑"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_292"},{"id":293,"type":"multiple","stem":"根据《陕西省安全生产条例》，生产经营单位的（   ）同为本单位安全生产责任人，对本单位安全生产全面负责。","options":["A．法定代表人","B．项目经理","C．实际控制人","D．实际负责人","E．分管安全的负责人"],"answer":"ACD","hasImage":false,"image":null,"globalId":"law_多选_293"},{"id":294,"type":"multiple","stem":"根据《陕西省安全生产条例》，县级以上应急管理部门负责本行政区域内安全生产的（   ）、宣传教育培训等综合性工作，对安全生产工作实施综合监督管理。","options":["A．执法监督","B．事故调查处理","C．应急救援管理","D．生产进度","E．统计分析"],"answer":"ABCE","hasImage":false,"image":null,"globalId":"law_多选_294"},{"id":295,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，县级以上人民政府负有安全生产监督管理职责的部门以及生产经营单位应当建立健全安全生产（   ）机制。","options":["A．齐抓共管","B．风险分级管控","C．一岗双责","D．责任追究","E．隐患排查治理"],"answer":"BE","hasImage":false,"image":null,"globalId":"law_多选_295"},{"id":296,"type":"multiple","stem":"根据《陕西省安全生产条例》，县级以上人民政府应当设立安全生产专项资金，用于（   ）以及安全生产工作奖励等方面。","options":["A．应急救援体系建设","B．安全技术项目推广应用","C．公共安全防护设施采购","D．重特大事故应急救援","E．公共隐患治理"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_296"},{"id":297,"type":"multiple","stem":"（   ）生产经营单位应当依法取得相应的安全生产许可证或者经营许可证。","options":["A．矿山","B．建筑施工","C．危险化学品","D．烟花爆竹","E．民用爆炸物品"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_297"},{"id":298,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位的全员安全生产责任制应当明确各岗位的（  ）等内容。","options":["A．管理体系","B．责任范围","C．考核标准","D．应急救援","E．责任人员"],"answer":"BCE","hasImage":false,"image":null,"globalId":"law_多选_298"},{"id":299,"type":"multiple","stem":"根据《陕西省生产经营单位安全生产主体责任规定》，生产经营单位应当根据本单位的生产经营特点，对生产工序、设备进行风险辨识并确定风险等级，进行（   ）。","options":["A．日常安全生产巡查","B．定期进行专项安全生产排查","C．每月至少进行一次综合安全生产检查","D．季节性安全检查","E．节假日前后安全检查"],"answer":"ABC","hasImage":false,"image":null,"globalId":"law_多选_299"},{"id":300,"type":"multiple","stem":"根据《陕西省安全生产条例》，煤矿、非煤矿山、危险化学品、烟花爆竹、（   ）等高危行业领域的生产经营单位应当投保安全生产责任保险。","options":["A．交通运输","B．建筑施工","C．民用爆炸物品","D．金属冶炼","E．渔业生产"],"answer":"ABCDE","hasImage":false,"image":null,"globalId":"law_多选_300"},{"id":301,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，应当按照国家有关规定进行安全评价的建设项目有（   ）。","options":["A．矿山建设项目","B．金属冶炼建设项目","C．人员密集场所建设项目","D．用于生产、储存、装卸危险物品的建设项目","E．学校建设项目"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_301"},{"id":302,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位从业人员需履行的义务有（   ）。","options":["A．遵守本单位的安全生产规章制度和操作、作业规程","B．正确使用劳动防护用品","C．接受安全生产教育和培训","D．及时报告事故隐患和不安全因素","E．上岗前进行岗位安全检查"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_302"},{"id":303,"type":"multiple","stem":"根据《陕西省安全生产条例》，生产经营单位的（   ）不良信息，应纳入本省公共信用信息系统。","options":["A．发生较大以上生产安全责任事故的","B．未依法取得安全生产相关许可或者许可被暂扣、吊销期间从事相关生产经营活动的","C．承担安全评价、认证、检测、检验职责的机构及其直接责任人员有租借资质、挂靠、出具虚假报告或者证书行为的","D．负有安全生产监督管理职责的部门作出行政处罚后，有执行能力拒不执行或者逃避执行的","E．因安全生产条件不达标被媒体曝光的"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_303"},{"id":304,"type":"multiple","stem":"根据《中华人民共和国行政处罚法》，作出（   ）处罚决定的，应当告知当事人有要求举行听证的权利。","options":["A．责令停产停业","B．降低资质等级、吊销许可证件","C．较大数额罚款","D．没收较大数额违法所得、没收较大价值非法财物","E．刑事拘留"],"answer":"ABCD","hasImage":false,"image":null,"globalId":"law_多选_304"},{"id":305,"type":"multiple","stem":"根据《陕西省安全生产条例》，以下属于条例制定目的是（   ）。","options":["A．加强安全生产工作","B．防止和减少生产安全事故","C．提高安全生产工作绩效","D．保障人民群众生命和财产安全","E．促进经济社会持续健康发展"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_305"},{"id":306,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，以下属于生产经营单位主要负责人的安全生产工作职责的有（   ）。","options":["A．建立健全并落实本单位全员安全生产责任制","B．制止和纠正违章指挥、强令冒险作业、违反操作规程的行为","C．保证本单位安全生产投入的有效实施","D．组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制","E．组织制定并实施本单位的生产安全事故应急救援预案"],"answer":"ACDE","hasImage":false,"image":null,"globalId":"law_多选_306"},{"id":307,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，生产经营单位主要负责人是生产经营活动和安全生产工作的决策者和指挥者，对于落实安全生产责任制，加强安全管理，确保安全生产至关重要。施工单位主要负责人的安全责任主要包括（   ）。","options":["A．建立健全安全生产责任制","B．组织制定安全生产规章制度和操作规程","C．对安全生产进行现场监督检查","D．保证本单位安全生产条件所需资金的投入","E．对所承担的建设工程进行定期和专项安全检查，并做好安全检查记录"],"answer":"ABDE","hasImage":false,"image":null,"globalId":"law_多选_307"},{"id":308,"type":"multiple","stem":"根据《中华人民共和国安全生产法》的要求，下列选项中关于生产经营单位主要负责人说法正确的是（   ）。","options":["A．组织或参与拟定本单位安全生产规章制度","B．组织或参与本单位安全生产教育和培训","C．构建安全风险分级管控和隐患排查治理双重预防体系","D．保证本单位安全生产投入的有效实施","E．加强安全生产标准化建设"],"answer":"CDE","hasImage":false,"image":null,"globalId":"law_多选_308"},{"id":309,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，关于生产经营单位主要负责人职责的说法，正确的有（   ）。","options":["A．组织制定并实施本单位安全生产规章制度和操作规程","B．督促、检查本单位的安全生产工作，及时消除生产安全事故隐患","C．督促落实本单位重大危险源的安全管理措施","D．组织制定并实施本单位的生产安全事故应急救援预案","E．检查本单位的安全生产状况，及时排查生产安全事故隐患，提出改进安全生产管理的建议"],"answer":"ABD","hasImage":false,"image":null,"globalId":"law_多选_309"},{"id":310,"type":"multiple","stem":"根据《中华人民共和国安全生产法》，下列属于生产经营单位主要负责人职责的有（   ）。","options":["A．组织本单位安全生产教育和培训，如实记录安全生产教育和培训情况","B．制止和纠正违章指挥、强令冒险作业、违反操作规程的行为","C．督促落实本单位重大危险源的安全管理措施","D．及时、如实报告生产安全事故","E．督促、检查本单位的安全生产工作，及时消除生产安全事故隐患"],"answer":"DE","hasImage":false,"image":null,"globalId":"law_多选_310"},{"id":311,"type":"multiple","stem":"根据《中华人民共和国安全生产法》的规定，下列关于生产经营单位的安全生产管理人员职责的说法，正确的有（   ）。","options":["A．组织本单位安全生产教育和培训，如实记录安全生产教育和培训情况","B．健全本单位安全生产责任制，实施本单位安全生产教育和培训计划","C．制止和纠正违章指挥、强令冒险作业、违反操作规程的行为","D．组织开展危险源辨识和评估，督促落实本单位重大危险源的安全管理措施","E．组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制"],"answer":"ACD","hasImage":false,"image":null,"globalId":"law_多选_311"},{"id":312,"type":"multiple","stem":"根据《中华人民共和国安全生产法》的规定，下列关于生产经营单位的安全生产管理人员职责的说法，正确的有（   ）。","options":["A．组织本单位安全生产教育和培训，如实记录安全生产教育和培训情况","B．健全本单位安全生产责任制，实施本单位安全生产教育和培训计划","C．制止和纠正违章指挥、强令冒险作业、违反操作规程的行为","D．保证本单位安全生产投入的有效实施，组织制定本单位安全生产操作规程","E．督促落实本单位重大危险源的安全管理措施"],"answer":"ACE","hasImage":false,"image":null,"globalId":"law_多选_312"},{"id":313,"type":"multiple","stem":"根据《中华人民共和国安全生产法》的规定，下列关于生产经营单位的安全生产管理人员职责的说法，正确的有（   ）。","options":["A．及时、如实报告生产安全事故","B．组织本单位安全生产教育和培训，如实记录安全生产教育和培训情况","C．督促落实本单位重大危险源的安全管理措施","D．保证本单位安全生产投入的有效实施","E．制止和纠正违章指挥、强令冒险作业、违反操作规程的行为"],"answer":"BCE","hasImage":false,"image":null,"globalId":"law_多选_313"},{"id":314,"type":"multiple","stem":"根据《中华人民共和国安全生产法》的规定，下列属于生产经营单位安全生产管理人员职责的有（   ）。","options":["A．组织或参与拟定本单位安全生产规章制度、操作规程","B．组织本单位安全生产教育和培训，如实记录安全生产教育和培训情况","C．组织制定并实施本单位的生产安全事故应急救援预案","D．组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制","E．加强安全生产标准化建设"],"answer":"AB","hasImage":false,"image":null,"globalId":"law_多选_314"},{"id":315,"type":"multiple","stem":"根据《中华人民共和国安全生产法》的规定，下列属于生产经营单位安全生产管理人员职责的有（   ）。","options":["A．组织制定并实施本单位安全生产规章制度和操作规程","B．组织本单位安全生产教育和培训，如实记录安全生产教育和培训情况","C．组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制","D．加强安全生产标准化建设","E．督促落实本单位安全生产整改措施"],"answer":"BE","hasImage":false,"image":null,"globalId":"law_多选_315"}]};